quests[62307] = { id = 62307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 3" }
quests[62308] = { id = 62308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantel der Meisterschaft", description = "Ihr habt viel getan, um Euch als <vielversprechender Akolyth/vielversprechende Akolythin> zu beweisen. Eure Oberen haben mitgeteilt, dass Ihr bereit seid, Euch der Prüfung zu stellen, um den Mantel des Ritualisten anzulegen.\n\nWenn Ihr soweit seid, beginnt Ihr mit dem Ritual der Ahnenbeschwörung, um einen Ältestengeist von Maldraxxus heraufzubeschwören. Besiegt den Geist und beweist Euren Mut!", sourceObjective = "Beschwört über das Oberste Arkanum einen Ältestengeist von Maldraxxus herauf und besiegt ihn. Für das Heraufbeschwören werden drei Spielercharaktere benötigt.", completion = "Ihr habt Euch als würdig erwiesen, den Mantel anzulegen, Akolyth.\n\nTragt ihn mit Ehre und Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[62309] = { id = 62309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Secutor Mevix", sourceObjective = "{name}, schön, Euch wiederzusehen!\n\nNach Eurem Erfolg gegen das Haus der Konstrukte verlangt es Secutor Mevix nach weiteren Taten auf dem Schlachtfeld.\n\nLasst einen eifrigen Soldaten nicht hier in Trübsal versinken. Gebt ihm eine Aufgabe!", sourceObjectiveStatus = "unverified-source-field" }
quests[62312] = { id = 62312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Gunn Knochenschlinger", sourceObjective = "Es gibt heute eine aufregende Entwicklung, {name}!\n\nIhr müsst einen ziemlichen Eindruck hinterlassen haben. Gunn Knochenschlinger, einer der Champions des Theaters der Schmerzen, verlangt, sich uns hier anzuschließen. Er verlangt es!", sourceObjectiveStatus = "unverified-source-field" }
quests[62313] = { id = 62313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Rencissa der Dynamo", sourceObjective = "{name}! Tretet näher, kommt, kommt!\n\nIch habe soeben erfahren, dass niemand anderes als Rencissa der Dynamo auf dem Weg hierher ist, um für Euch zu kämpfen. Rencissa! Der Dynamo!\n\nWen sollen wir zuerst von ihr töten lassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[62314] = { id = 62314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Khaliiq", sourceObjective = "Hört zu, {name}. Wir brauchen mehr Augen da draußen auf dem Schlachtfeld.\n\nEs gibt zu viele Bedrohungen, die auf uns zukommen, und nicht genug Informationen.\n\nSeht, ob Khaliiq der Aufgabe gewachsen ist. Ihr habt richtig gehört, ich sagte mehr Augen!", sourceObjectiveStatus = "unverified-source-field" }
quests[62315] = { id = 62315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Seuchi", sourceObjective = "Heute gibt es etwas Seltsames, {name}.\n\nMarileth ist vorbeigekommen, um zu sagen, dass sich sein Schleim Seuchi noch niedergeschlagener als sonst fühlt und hat gefragt, ob wir ihn bei Laune halten könnten.\n\nSieht das hier wie eine Schleimpension aus? Seuchi kann sich seinen Unterhalt verdienen wie wir alle! Schafft ihn da raus, Soldat!", sourceObjectiveStatus = "unverified-source-field" }
quests[62316] = { id = 62316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Rathan", sourceObjective = "Eure Hingabe an Maldraxxus ist inspirierend, {name}.\n\nRathan hat darum gebeten, hier am Sitz zum Wohle von Maldraxxus in unsere Reihen aufgenommen zu werden. Seine Expertise wird eine Bereicherung sein!\n\nIch vermute, er will auch Emeni im Auge behalten, aber das habt Ihr nicht von mir gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[62317] = { id = 62317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufkommende Zweifel", description = "<Hier wurde eine Nachricht für Kel'Thuzad hinterlassen. Er scheint sie noch nicht gelesen zu haben.>\n\nBaron, ich traue <Eurem neuen Lieblingsakolythen/Euer neuen Lieblingsakolythin> nicht. <Er/Sie> scheint seit der Rückkehr vom Ritual mit den Kyrianerüberresten nicht ganz bei der Sache zu sein.\n\nEuer Schaffen ist zu bedeutend, um irgendwelche Diskrepanzen zu ignorieren. Ihr solltet <den Akolythen/die Akolythin> loswerden.\n\nEuch treu ergeben,\n\nZauberer Vutral", sourceObjective = "Besiegt Zauberer Vutral im Verlies der Seelen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62320] = { id = 62320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Passende Aufmachung", description = "Ah, das ist doch Kel'Thuzads <Lieblingsakolyth/Lieblingsakolythin>? Ich kann überhaupt nicht verstehen, wie sich ein Baron wie er mit so... trister Gesellschaft abgeben kann.\n\nWann habt Ihr Euch zum letzten Mal im Spiegel angesehen? Eure ausgeblichene Kleidung wird Eurem Stand nicht gerecht.\n\nIch würde mich ja selbst darum kümmern, Eure farblose Erscheinung etwas aufzufrischen, aber mir fehlt die von dem Haus bevorzugte Amethystinfarbe.\n\nIhr könntet vielleicht selbst etwas davon beschaffen. Die Hexenmeister bewahren normalerweise etwas davon in ihren Folianten und Altären auf.", sourceObjective = "Sammelt 10 Amethystinpulver vom Haus der Rituale.", progress = "Ich brauche große Mengen Amethystinpulver, wenn ich das...\n\n<Moret macht ausladende Gesten.>\n\n...in Ordnung bringen soll.", completion = "Es erleichtert mich sehr, dass Eure bleiche Kleidung mir nicht mehr das Sichtfeld verdirbt.\n\nSorgt dafür, dass sie zukünftig besser in Form ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[62321] = { id = 62321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 1" }
