quests[62361] = { id = 62361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit, sich vorzustellen", description = "Jetzt ist alles klar mit Eurem neuen Gräber. Also ruft ihn her und stellt Euch offiziell vor.", sourceObjective = "Sprecht mit Eurem neuen Gräberbutler.", completion = "Ich bin so verwirrt...", sourceObjectiveStatus = "unverified-source-field" }
quests[62362] = { id = 62362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüchtige Reaktionen", description = "Der lebende Schleim in Maldraxxus erzeugt einen mächtigen Katalysator, der vom Haus der Augen in vielen seiner Giften genutzt wird. Die Substanz wird ständig gebraucht.\n\nEs wäre uns eine große Hilfe, wenn Ihr ein wenig davon besorgen könntet.", sourceObjective = "Sammelt 15 animierte Katalysatoren vom Schleim um Maldraxxus.", progress = "Sorgt Euch nicht. Trotz seiner Erscheinung ist der Katalysator selbst nicht toxisch.", completion = "Das ist doch eine ganze Menge. Ich werde sie gut einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62363] = { id = 62363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwer gehoben", description = "Die stärkeren Mitglieder des Hauses der Auserwählten nehmen meist eine ganz bestimmte Gestalt an. Ihr habt sicher die größeren Kämpfer im Haus gesehen?\n\nSie sind die größte Gefahr ihrer Streitmacht. Dezimiert sie.", sourceObjective = "Tötet 20 Krieger im Haus der Auserwählten.", completion = "Ihr habt meinen Dank. Die Auserwählten sind uns in schierer Körperkraft hoffnungslos überlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62364] = { id = 62364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlimmes Studium", description = "Totenbeschwörer und Lichs nutzen oftmals die Hilfe mächtiger Folianten in ihren Ritualen. Diese Folianten findet man überall dort, wo Mitglieder des Hauses der Rituale aktiv sind, wo es nun seinen Einflussbereich erweitert hat.\n\nFindet und zerstört sie. Das wird ihre abscheulichen Experimente nicht verhindern, aber vielleicht verzögern.", sourceObjective = "Zerstört 15 Folianten der Rituale.", completion = "Gut. Das Haus der Rituale wird sich hüten, sich das Haus der Augen zum Feind zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62365] = { id = 62365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sorgsame geschaffene Schöpfungen", description = "Wie könnte man seine Feinde besser aufhalten, als ihre eigenen Experimente gegen sie einzusetzen?\n\nZu unserem Glück haben einige unserer... Freunde ein paar Proben unbewacht zurückgelassen. Und ich weiß auch schon, wo wir sie testen werden...\n\nSo bedrohlich sie auch wirken, diese Monstrositäten da unten sind anfällige Schöpfungen.\n\nEs wäre doch eine Schande, wenn Ihr an einen Teil der Ausrüstung kommen und den Prozess unterbrechen könntet...", sourceObjective = "Findet einen experimentellen Seuchenverbreiter und füllt ihn mit experimenteller Flüssigkeit. Verwendet den Seuchenverbreiter, um 3 rekonstruierte Monstrositäten in den Fleischwerken zu vernichten.", progress = "Läuft alles nach Plan?", completion = "Haha! Das lief besser als erwartet. Mit dem Beseitigen dieser Sauerei sind sie noch eine Weile beschäftigt!\n\nOh, also...\n\n<Dunkelreiterin Arly zeigt auf Eure Schulter.>\n\nDa klebt noch ein bisschen was an Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[62366] = { id = 62366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 3" }
quests[62367] = { id = 62367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 1" }
quests[62368] = { id = 62368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertrauen erneut erlangen", description = "Nun, {name}, es scheint, dass Ihr ernsthaft darum bemüht seid, unsere Gunst zurückzuerlangen.\n\nEs scheint, dass es Euch mit der Sühne ernst ist. Mit dieser Aufgabe könnt Ihr beweisen, dass Ihr gewillt seid, in unsere Reihen zurückzukehren.", sourceObjective = "Schließt die Aufgabe der Kyrianer ab.", completion = "Ihr habt also getan, wozu wir Euch aufgefordert haben, und wollt Euch uns erneut anschließen?\n\nWenn Ihr diese Aufgabe bei mir abschließt, werdet Ihr Euren derzeitigen Pakt verlassen und Euch wieder den Kyrianern anschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62371] = { id = 62371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirna Scithe: Warnende Stille", description = "Die Lieder von Tirna Scithe verstummen, seit der Hain schwindet, und nun ist alles still. Dromanin Oulfarrans Stimme wurde schon lange nicht mehr vernommen. Die Bäume flüstern von Halbschatten, missklingenden Liedern und sterbenden Wurzeln. Es sieht nicht gut aus.\n\n<Freund/Freundin> des Ardenwalds, reist nach Wurzelheim. Erforscht die Nebel und nehmt die Bedrohung von uns.", sourceObjective = "Besiegt Tred'ova in den Nebeln von Tirna Scithe.", completion = "Das Lied Eurer Hilfe wird in den Wurzeln gesungen. Ich danke Euch, Freund des Waldes.", sourceObjectiveStatus = "unverified-source-field" }
quests[62373] = { id = 62373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 2" }
quests[62374] = { id = 62374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 3" }
quests[62382] = { id = 62382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Unbekannte", description = "Kommt Ihr den alten Marasmius besuchen? Ich habe eine ganz besondere Aufgabe für Euch.\n\nEiner meiner Sprösslinge hat einen merkwürdigen Ort gefunden, einen Ort, den ich noch nie zuvor gesehen habe.\n\nIch bin nicht ganz sicher, was sich darin befindet oder ob es gefährlich ist. Aber dafür habe ich ja meine verlässlichen Pilzomanten!\n\nWas sagt Ihr, {name}? Bereit für ein Abenteuer?", sourceObjective = "Untersucht das unbekannte Gebiet.", completion = "Sie schien nett zu sein. Das Pilzkönigreich, nicht wahr? Hm, nie davon gehört. Was die jungen Leute heutzutage treiben...", sourceObjectiveStatus = "unverified-source-field" }
quests[62385] = { id = 62385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 1" }
quests[62386] = { id = 62386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 2" }
quests[62387] = { id = 62387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 3" }
quests[62388] = { id = 62388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haus der Rituale", description = "Hinter diesem Krieg stecken die Ritualisten. Jeder Akt des Verrats geschah auf ihren Befehl hin.\n\nAlleine mit Waffen können wir ihrer Hexerei nicht beikommen. Unser Sieg hängt davon ab, wie gut wir ihre Pläne kennen.\n\nVerstärkt weiter unsere Truppen. Ich suche derweil nach einem Weg, das Haus der Rituale zu infiltrieren.", sourceObjective = "Erhöht Euren Ruhm.", completion = "Wir scheinen einen Weg ins Haus der Rituale gefunden zu haben.\n\nHaltet diesen Lich nicht für einen Verbündeten. Er verfolgt nur seine eigenen Ziele. Doch fürs Erste überschneiden sie sich... und das sollten wir zu unserem Vorteil nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62389] = { id = 62389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertrauen erneut erlangen", description = "Das war der erste Schritt zur Wiedererlangung unseres Vertrauens.\n\nJetzt müsst Ihr beweisen, dass dies nicht wieder ein irrtümlicher Beginn unserer gegenseitigen Beziehung war.\n\nMit dieser letzten Aufgabe könnt Ihr beweisen, dass Ihr gewillt seid, in unsere Reihen zurückzukehren.", sourceObjective = "Schließt die Aufgabe der Venthyr ab.", completion = "Ihr habt also getan, wozu wir Euch aufgefordert haben, und wollt Euch uns erneut anschließen?", sourceObjectiveStatus = "unverified-source-field" }
quests[62390] = { id = 62390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichensammeln", description = "Ich kenne ein paar Fleischformer, die vor dem Haus der Konstrukte arbeiten. Wenn wir Reagenzien für sie finden, können sie Konstrukte für unseren Krieg beisteuern.\n\nDas Haus der Konstrukte quillt über vor überflüssigen Körperteilen. Findet sie und bringt sie her.", sourceObjective = "Sammelt 30 Monstrositätenteile in Maldraxxus.", progress = "Alles, was Ihr findet, kann von Nutzen sein.", completion = "Ich werde sie den Fleischformern geben. Wenn wir nicht genug Soldaten haben, müssen wir eben welche bauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62391] = { id = 62391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maldraxxus mobilisieren", description = "Es wird schwer werden, Kel'Thuzad in seiner Nekropole zu erreichen.\n\nGeht jetzt. Es wird eine Weile dauern, bis unsere Streitkräfte groß genug sind, um seine Verteidigung zu durchbrechen.", sourceObjective = "Erhöht Euren Ruhm.", completion = "Unsere Streitmacht ist bereit.\n\nLasst uns das beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[62392] = { id = 62392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertrauen erneut erlangen", description = "Ihr seid zurück. Beeindruckend. Vielleicht seid Ihr wirklich bereit, ein neues Leben zu beginnen.\n\nIch möchte, dass Ihr noch eine Aufgabe für uns abschließt. Um Euren Willen zur Veränderung zu beweisen. \n\nWir haben zwar keine Zweifel, aber Ihr müsst verstehen, dass Euer vorheriges Betragen Anlass gibt, an Eurem Willen zu zweifeln.", sourceObjective = "Schließt die Aufgabe der Nachtfae ab.", completion = "Ihr habt also getan, wozu wir Euch aufgefordert haben, und wollt Euch uns erneut anschließen?", sourceObjectiveStatus = "unverified-source-field" }
quests[62393] = { id = 62393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertrauen erneut erlangen", description = "Ihr scheint noch genauso stark wie zuvor zu sein.\n\nDie Frage ist aber, wie viel Loyalität Ihr noch in Euch habt?\n\nIch habe noch eine Aufgabe für Euch, um Eure Loyalität unter Beweis zu stellen.", sourceObjective = "Schließt die Aufgabe der Nekrolords ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[62394] = { id = 62394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haus im Niedergang", description = "Unsere Streitmacht sammelt sich.\n\nBald schon werden wir gegen das Haus der Rituale ziehen.\n\nHelft dabei, unsere Position weiter zu stärken.", sourceObjective = "Erhöht Euren Ruhm.", sourceObjectiveStatus = "unverified-source-field" }
quests[62400] = { id = 62400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzen überschreiten!", description = "Ah, Ihr kommt gerade recht. Ich habe eine aufregende Entdeckung gemacht.\n\nEs ist mir gelungen, eine Verbindung in einer Entfernung herzustellen, die ich noch nie zuvor erreicht habe.\n\nIhr wollt wissen, wie ich das gemacht habe? Mit harter Arbeit! Aber das wusstet Ihr bereits. Ihr arbeitet fast so hart wie ich. Genau deswegen seid Ihr hier!\n\nSeid Ihr bereit für ein noch aufregenderes Abenteuer?", sourceObjective = "Untersucht das unbekannte Gebiet.", completion = "Ich erinnere mich an diese Leute. Die machen nur Ärger. \n\nSie sollten besser in ihrer eigenen Welt bleiben!\n\nGute Aufräumarbeit im Haus.", sourceObjectiveStatus = "unverified-source-field" }
quests[62401] = { id = 62401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsame Runensteine", description = "Die Diener des Lichkönigs trugen einst Geißelsteine bei sich, die ihr dunkler Meister ihnen gegeben hatte.\n\nAn den Leichen der Untoten wurden neue gefunden. Wir kennen ihren Zweck nicht... aber sie wurden von noch unheimlicherer Magie berührt.\n\nWenn Ihr die Geißel in Eiskrone tötet, haltet die Augen nach solchen Steinen offen. Wenn Ihr sie mir zurückbringt, werde ich sie den Beichtpaten zum Studium übergeben.", sourceObjective = "Sammelt verdunkelte Geißelsteine und pechschwarze Geißelsteine von untoten Truppen in Eiskrone.", progress = "Was läuft das Töten der Untoten?", completion = "Ich werde sie sofort den Beichtpaten übergeben. Hinter diesen Geißelsteinen steckt mehr, als es den Anschein hat.\n\nVielleicht werden sie uns mehr Wissen über die Kreaturen vermitteln, die uns aus dem Riss im Himmel angreifen.\n\nWenn Ihr bei Euren Abenteuern weitere Geißelsteine findet, bringt sie bitte zu mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[62402] = { id = 62402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeitwanderungskampagnen" }
quests[62403] = { id = 62403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ebertran", description = "Die Eber in Maldraxxus haben eine spezielle Eigenheit. Ihre Hauer absorbieren Flüssigkeiten. Je nachdem, wo die Eber gewesen sind, können die Hauer mächtige Gifte oder alchemistische Wundermittel beinhalten.\n\nEs braucht schon Erfahrung, um zu erkennen, wie der Knochen beschaffen ist. Bringt mir einfach ganz viele davon und ich werde sehen, ob etwas Wertvolles dabei ist.", sourceObjective = "Sammelt 25 blutige Hauer von Ebern in Maldraxxus.", progress = "Passt auf, dass die Knochen Eure Haut nicht zu lange berühren. Das kann zu einer Irritation führen.", completion = "Das ist eine ganze Menge. Da ist sicher etwas Nützliches dabei.", sourceObjectiveStatus = "unverified-source-field" }
quests[62406] = { id = 62406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stab des Primus", description = "Der Stab des Primus. Das letzte Stück des Ornats unseres Anführers.\n\nEs erfüllt mich mit Stolz, diese Hallen wieder aufzubauen. Ihr solltet das gleiche erhabene Gefühl haben.\n\nDie Statue wartet auf Euch, {name}. Bringt diesem Reich Ruhm.", sourceObjective = "Platziert den Stab des Primus an der Statue des Primus.", completion = "Ich spüre Macht. Macht und Ruhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[62407] = { id = 62407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blütengestank", description = "Mein Gas ist das mächtigste in ganz Maldraxxus. Allerdings habe ich von Behauptungen gehört, dass es nicht das stärkste in den Schattenlanden sei.\n\nAngeblich wachsen Pflanzen im Ardenwald, deren Blüten noch penetranter riechen als mein Gas. Was für ein Unsinn!\n\nWir müssen diese Pflanze finden und ergründen, ob ihr Gestank wirklich so stark ist, wie behauptet wird. Vielleicht kann ich sie ja mit meinem eigenen Gas mischen!", sourceObjective = "Helft Gasbeutel, Faulblütenblätter zu sammeln.", progress = "Spaß beim Blümchen pflücken?", completion = "Wie ist es nur möglich, dass er noch mehr stinkt als vorher?!\n\nIgitt. Zumindest eine Art Erfolg.", sourceObjectiveStatus = "unverified-source-field" }
quests[62414] = { id = 62414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeugen", description = "Es wird uns nicht helfen, wenn Ihr Euch als Nelesis verkleidet, wenn Kel'Thuzad erfährt, dass sie getötet wurde.\n\nIhr müsst sicherstellen, dass niemand überlebt, der gesehen hat, wie Ihr die Höhle betreten habt.", sourceObjective = "Tötet 10 lichverschworene Kämpfer vor dem Haus der Rituale.", completion = "Keiner am Leben, der Alarm schlagen könnte? Gut.\n\nLasst uns den Plan weiterführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62417] = { id = 62417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzen überschreiten!", description = "Ah, Ihr kommt gerade recht. Ich habe eine aufregende Entdeckung gemacht.\n\nEs ist mir gelungen, eine Verbindung in einer Entfernung herzustellen, die ich noch nie zuvor erreicht habe.\n\nIhr wollt wissen, wie ich das gemacht habe? Mit harter Arbeit! Aber das wusstet Ihr bereits. Ihr arbeitet fast so hart wie ich. Genau deswegen seid Ihr hier!\n\nSeid Ihr bereit für ein noch aufregenderes Abenteuer?", sourceObjective = "Untersucht das unbekannte Gebiet.", progress = "Ich spüre einen Luftzug auf der anderen Seite. Das wird wohl bedeuten, dass es nicht unterirdisch ist.", completion = "Von Beruf Blumen zu pflücken, ist harte, ehrliche Arbeit.\n\nUnd diesen elenden Spriggans einen Tritt in den Allerwertesten zu verpassen, ist auch nicht zu verachten. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[62420] = { id = 62420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnapperseele", description = "<Die Schnapperseele ist entschlossen. Ihr könnt jetzt die Gestalt der Drachenschildkröte nutzen.>", sourceObjective = "Bringt die Schnapperseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah. Die Essenz der Drachenschildkröte! Eine liebreizende Gestalt. Wenn Ihr sie nutzen wollt, ist sie die Eure.", sourceObjectiveStatus = "unverified-source-field" }
quests[62421] = { id = 62421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schluckerseele", description = "<Die Schluckerseele ist geduldig und ruhig. Ihr könnt jetzt die Gestalt des Schluckers nutzen.>", sourceObjective = "Bringt die Schluckerseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ihr könnt die Gestalt des Schluckers jetzt herbeirufen und nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62422] = { id = 62422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ardenmottenseele", description = "<Im Ardenwald gibt es die Ardenmotte überall. Diese anmutigen Kreaturen besitzen eine verborgene Kraft. Ihre Magie kann schlimm gefolterte Seele trösten... oder die Unachtsamen in den ewigen Schlaf schicken. Ihr könnt jetzt die Gestalt der Motte nutzen.>", sourceObjective = "Bringt die Ardenmottenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, die Motte. Solch eine wunderschöne Kreatur. Ihr könnt Ihre Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62423] = { id = 62423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärenseele", description = "<Die Bärenseele ist standhaft und mutig. Ihr könnt jetzt die Gestalt des Bären nutzen.>", sourceObjective = "Bringt die Bärenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah. Das Herz des Bären! Eine kraftvolle Gestalt. Wenn Ihr sie nutzen wollt, ist sie die Eure.", sourceObjectiveStatus = "unverified-source-field" }
quests[62424] = { id = 62424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kranichseele", description = "<Die Kranichseele tanzt anmutig. Ihr könnt jetzt die Gestalt des Kranichs nutzen.>", sourceObjective = "Bringt die Kranichseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Die Anmut des Kranichs! Eine liebreizende Gestalt. Wenn Ihr sie nutzen wollt, ist sie die Eure.", sourceObjectiveStatus = "unverified-source-field" }
quests[62425] = { id = 62425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleierflügelseele", description = "<Anmutig, gefährlich, mächtig. Im Ardenwald fürchtet man keine Kreatur mehr für ihr rabiates Verteidigungsverhalten, wenn es um Familie oder Territorium geht, als den Schleierflügel.\n\nIhr habt einen Feind besiegt, der nicht nur den Ardenwald, sondern die ganzen Schattenlande bedroht hat. Champion des Ardenwalds, dafür habt Ihr einen besonderen Segen verdient. Ihr könnt nun die Essenz der Schleierflügel anrufen und ihre Gestalt annehmen.>", sourceObjective = "Bringt die Schleierflügelseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt seltenen Mut gezeigt, {name}. Dieser Wald erkennt Eure Taten an. Mögen Eure heldenhafte Verteidigung unserer Grenzen und Eure Liebe zu unseren Aufgaben in Liedern besungen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[62426] = { id = 62426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greifenseele", description = "<Die Greifenseele ist schnell und wendig. Ihr könnt jetzt die Gestalt des Greifen nutzen.>", sourceObjective = "Bringt die Greifenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah. Ihr seid rasant wie ein Greif. Ihr dürft die Gestalt des Greifen jederzeit nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62427] = { id = 62427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hippogryphenseele", description = "<Die Hippogryphenseele ist intelligent und tapfer. Ihr könnt jetzt die Gestalt des Hippogryphen nutzen.>", sourceObjective = "Bringt die Hippogryphenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der tapfere Hippogryph. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62428] = { id = 62428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pferdeseele", description = "<Die Pferdeseele ist ein Freigeist und loyal. Ihr könnt jetzt die Gestalt des gehörnten Pferdes nutzen.>", sourceObjective = "Bringt die Pferdeseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Eine majestätische Gestalt, so viel ist sicher. Wenn Ihr sie nutzen wollt, ist sie die Eure.", sourceObjectiveStatus = "unverified-source-field" }
quests[62429] = { id = 62429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Löwenseele", description = "<Die Löwenseele ist mächtig und mutig. Ihr könnt jetzt die Gestalt des Löwen nutzen.>", sourceObjective = "Bringt die Löwenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Löwe. Eine wundervolle Gestalt. Wenn Ihr sie nutzen wollt, ist sie die Eure.", sourceObjectiveStatus = "unverified-source-field" }
quests[62430] = { id = 62430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elchseele", description = "<Die Elchseele beschützt und erduldet viel. Ihr könnt jetzt die Gestalt des Elchs nutzen.>", sourceObjective = "Bringt die Elchseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Der Elch! Perfekte Wahl. Wenn Ihr die Gestalt nutzen wollt, ist sie die Eure.", sourceObjectiveStatus = "unverified-source-field" }
quests[62431] = { id = 62431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenpirscherseele", description = "<Die Schattenpirscherseele ist trickreich und vorsichtig. Ihr könnt jetzt die Gestalt des Schattenpirschers nutzen.>", sourceObjective = "Bringt die Schattenpirscherseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Der Schattenpirscher! Nutzt diese Gestalt, um im Wald auf Beute zu lauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[62432] = { id = 62432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eulenkatzenseele", description = "<Die Eulenkatzenseele ist eine durchtriebene Täuscherin. In ihr finden viele tierische Eigenschaften zu einer spielerischen Balance zusammen, die ständig nach neuen Herausforderungen sucht. Ihr könnt jetzt die Gestalt der Eulenkatze nutzen.>", sourceObjective = "Bringt die Eulenkatzenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, ja. Ihr habt viele Herausforderungen durch Teamwork gemeistert. Ich verstehe, warum Ihr nun die Gestalt der Eulenkatze nutzen möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[62433] = { id = 62433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptorenseele", description = "<Die Raptorenseele ist loyal und unerschütterlich. Ihr könnt jetzt die Gestalt des Raptors nutzen.>", sourceObjective = "Bringt die Raptorenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Raptor! Ihr könnt jetzt die Gestalt des Raptors nutzen, wenn Ihr wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[62434] = { id = 62434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenhirschseele", description = "<Die Runenhirschseele ist ruhig und ausdauernd. Ihr könnt jetzt die Gestalt des Runenhirschs nutzen.>", sourceObjective = "Bringt die Runenhirschseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Die Runenhirsche! Sie sind schon lange Begleiter der Nachtfae. Ihr könnt ihre Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62435] = { id = 62435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hirschseele", description = "<Die Hirschseele ist edel und mächtig. Ihr könnt jetzt die Gestalt des Hirschs nutzen.>", sourceObjective = "Bringt die Hirschseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Hirsch. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62436] = { id = 62436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreischerseele", description = "<Die Kreischerseele ist flink und loyal. Ihr könnt jetzt die Gestalt des verschleierten Kreischers nutzen.>", sourceObjective = "Bringt die Kreischerseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ihr könnt die Gestalt des verschleierten Kreischers jetzt nutzen, wenn Ihr wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[62437] = { id = 62437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tigerseele", description = "<Die Tigerseele ist stolz und mächtig. Ihr könnt jetzt die Gestalt des Tigers nutzen.>", sourceObjective = "Bringt die Tigerseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ihr könnt die Gestalt des Tigers jetzt herbeirufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62438] = { id = 62438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsseele", description = "<Die Wolfsseele ist wild und ein freigeistiger Beschützer. Ihr könnt jetzt die Gestalt des Wolfs nutzen.>", sourceObjective = "Bringt die Wolfsseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Wolf. Was für eine edle Seele. Ihr könnt nun die Seelengestalt des Wolfs nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62439] = { id = 62439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsfalkenseele", description = "<Die Wolfsfalkenseele ist ein trickreicher Jäger. Ihr könnt jetzt die Gestalt des Wolfsfalken nutzen.>", sourceObjective = "Bringt die Wolfsfalkenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Der Wolfsfalke! Welch ein beeindruckender Jäger. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62440] = { id = 62440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wyvernseele", description = "<Die Wyvernseele ist stolz und entschlossen. Ihr könnt jetzt die Gestalt des Wyvern nutzen.>", sourceObjective = "Bringt die Wyvernseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Wyvern. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62441] = { id = 62441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechter Seelentausch", description = "Solange wir hier weit weg im Konservatorium arbeiten, dürfen wir nicht vergessen, den Rest des Paktes zu unterstützen.\n\nIch werde hier gebraucht, aber Ihr habt trotz Eurer kurzen Beine große Reichweite.\n\nBitte helft unserem Pakt, die nötige Anima zu beschaffen. In der Zwischenzeit werde ich einen weiteren Geist vorbereiten, den Ihr wiederherstellen könnt.", sourceObjective = "Sammelt Anima für Euer Sanktum.", completion = "Ihr dient dem Konservatorium weiterhin gut. Dafür habt Ihr meinen Dank.\n\nIhr dürft Euch jetzt einen Geist aus meiner persönlichen Sammlung für die Wiederherstellung aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62442] = { id = 62442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für den Pakt", description = "Ich habe fantastische Dinge über das Reich hinter diesem Garten gehört, aber ich bin zu alt, um mich selbst in Gefahr zu bringen.\n\nIhr seid jung und kräftig! Zieht hinaus in dieses Reich und kehrt mit Geschichten Eurer Abenteuer zu mir zurück!", sourceObjective = "Schließt eine Weltquest im Ardenwald ab.", completion = "Es hilft mir, dass Ihr diese Dinge für mich übernehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[62443] = { id = 62443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für den Pakt", description = "Ich habe fantastische Dinge über das Reich hinter diesem Garten gehört, aber ich bin zu alt, um mich selbst in Gefahr zu bringen.\n\nIhr seid jung und kräftig! Zieht hinaus in dieses Reich und kehrt mit Geschichten Eurer Abenteuer zu mir zurück!", sourceObjective = "Schließt eine Weltquest im Ardenwald ab.", completion = "Es hilft mir, dass Ihr diese Dinge für mich übernehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[62444] = { id = 62444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für den Pakt", description = "Ich habe fantastische Dinge über das Reich hinter diesem Garten gehört, aber ich bin zu alt, um mich selbst in Gefahr zu bringen.\n\nIhr seid jung und kräftig! Zieht hinaus in dieses Reich und kehrt mit Geschichten Eurer Abenteuer zu mir zurück!", sourceObjective = "Schließt eine Weltquest im Ardenwald ab.", progress = "Geht in die Schattenlande und kehrt mit Geschichten Eurer Heldentaten zu mir zurück.", completion = "Es hilft mir, dass Ihr diese Dinge für mich übernehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[62445] = { id = 62445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterstolz", description = "Ich möchte mehr über die stolzen Wesen in diesem Reich erfahren.\n\nWenn Ihr ein Wesen in einem Wildsamen platziert, wie Ihr es schon für mich getan habt, könnte ich den Wiederherstellungsprozess beobachten.", sourceObjective = "Platziert einen stolzen Geist in einem Wildsamen.", completion = "Das unterscheidet sich komplett von meiner Heimat, ist aber nichtsdestotrotz hochinteressant.", sourceObjectiveStatus = "unverified-source-field" }
quests[62447] = { id = 62447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltener und ungewöhnlicher Geist", description = "Ich habe ein Rätsel für Euch, {name}!\n\nJeder liebt spannende Rätsel! \n\nWir haben einen außergewöhnlichen Geist gefunden, doch er weigert sich, den Wildsamen zu betreten.\n\nJeder von uns, der ihn berührt, hat danach einen Traum, indem er sieht, wie Ihr gegen ein riesiges Tier kämpft. Erst nachdem Ihr es getötet habt, beginnt die Wiedergeburt dieses Geistes. \n\nWir sind uns sicher, dieses Tier zu kennen.\n\nSeid Ihr bereit herauszufinden, ob dieser Traum die Realität widerspiegelt?", sourceObjective = "Besiegt Tred'ova in den Nebeln von Tirna Scithe.", completion = "Ihr habt es geschafft! Ich kann nicht erklären, warum das funktioniert hat. Träume sind oft rätselhaft, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[62448] = { id = 62448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haussicherung", sourceObjective = "Erhöht Euren Ruhm.", completion = "Eure Taten haben die Aufmerksamkeit anderer Häuser geweckt... und derjenigen, die ihre Befehle in Frage stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62449] = { id = 62449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflicht eines Geistes", description = "Ich möchte mehr über die pflichtbewussten Wesen in diesem Reich erfahren.\n\nWenn Ihr ein Wesen in einem Wildsamen platziert, wie Ihr es schon für mich getan habt, könnte ich den Wiederherstellungsprozess beobachten.", sourceObjective = "Platziert einen pflichtbewussten Geist in einem Wildsamen.", completion = "Das unterscheidet sich komplett von meiner Heimat, ist aber nichtsdestotrotz hochinteressant.", sourceObjectiveStatus = "unverified-source-field" }
quests[62450] = { id = 62450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterherzen", description = "Ich möchte mehr über die ungezähmten Wesen in diesem Reich erfahren.\n\nWenn Ihr ein Wesen in einem Wildsamen platziert, wie Ihr es schon für mich getan habt, könnte ich den Wiederherstellungsprozess beobachten.", sourceObjective = "Platziert einen ungezähmten Geist in einem Wildsamen.", completion = "Das unterscheidet sich komplett von meiner Heimat, ist aber nichtsdestotrotz hochinteressant.", sourceObjectiveStatus = "unverified-source-field" }
quests[62451] = { id = 62451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Vorhallen" }
quests[62452] = { id = 62452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geistermacht", description = "Ich möchte mehr über die kämpferischen Wesen in diesem Reich erfahren.\n\nWenn Ihr ein Wesen in einem Wildsamen platziert, wie Ihr es schon für mich getan habt, könnte ich den Wiederherstellungsprozess beobachten.", sourceObjective = "Platziert einen kämpferischen Geist in einem Wildsamen.", completion = "Das unterscheidet sich komplett von meiner Heimat, ist aber nichtsdestotrotz hochinteressant.", sourceObjectiveStatus = "unverified-source-field" }
quests[62453] = { id = 62453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Unbekannte", description = "Kommt Ihr den alten Marasmius besuchen? Ich habe eine ganz besondere Aufgabe für Euch.\n\nEiner meiner Sprösslinge hat einen merkwürdigen Ort gefunden, einen Ort, den ich noch nie zuvor gesehen habe.\n\nIch bin nicht ganz sicher, was sich darin befindet oder ob es gefährlich ist. Aber dafür habe ich ja meine verlässlichen Pilzomanten!\n\nWas sagt Ihr, {name}? Bereit für ein Abenteuer?", sourceObjective = "Untersucht das unbekannte Gebiet.", progress = "Bleibt wachsam. Wir wissen nicht, wo das hinführt!", completion = "Ich weiß, dass Ihr harte Arbeit mögt, aber man muss sich von Zeit zu Zeit auch um sich selbst kümmern. Ich hoffe, Ihr hattet Spaß, habt Euch verausgabt und seid jetzt bereit, wieder zuzuschlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[62454] = { id = 62454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltener und ungewöhnlicher Geist", description = "Ich erwache. Einmal mehr existiere ich. Und doch...\n\nwohnt eine Leere in mir. Das verklingende Echo an ein Zuhause, das es nicht mehr gibt. So viele Wunder... so viel Pracht... verloren.\n\nJetzt fehlt mir der Sinn. Kein Schicksal. Kein Pfad.\n\nErzählt Ihr mir von diesem Ort, <Erwecker/Erweckerin>? Ich spüre, dass es hier viel zu wissen gibt. Viele Geheimnisse. Viele Wahrheiten.\n\nVielleicht erscheint mir dann ein neues Schicksal.", sourceObjective = "Sprecht mit Falir und überbringt die Essenzen aus den Reichen der Schattenlande.", completion = "Vielleicht erwartet mich eine neue Aufgabe.\n\nZumindest habt Ihr meine Neugier neu entfacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[62456] = { id = 62456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Andre Seite: Den Boss erledigen", description = "Hey, Mann. Lange nich' geseh'n!\n\nIch hab' 'n bisschen Ärger mit meinem Boss, Mueh'zala. Na, aber... keine Sorge. Euer alter Freund Bwonsamdi hat alles im Griff!\n\nIch brauch nur was Hilfe, um mein Mojo von 'n paar undankbaren Geschäftspartnern zurückzubekommen.\n\nIhr bringt mir das Mojo und wir erledigen den alt'n Mueh'zala ein für alle Mal!", sourceObjective = "Besiegt Mueh'zala auf der Andren Seite.", progress = "Erst holt Ihr das Mojo, dann krieg ich die Macht... und dann hol'n wir uns Mueh'zala!", completion = "Jetzt, da der alte Boss 'n gefesselter Zuhörer is', werden er und ich 'n paar neue Regelungen treff'n. Ihr geht jetz' besser, aber keine Sorge... wir seh'n uns bald!", sourceObjectiveStatus = "unverified-source-field" }
quests[62457] = { id = 62457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Große Schatzkammer", description = "\"Die Vorsehung.\" Was für ein Unsinn.\n\nDie Bediensteten sind derart blind vor Hingabe, dass Ihr Provosten auf ihr Köpfe fallen lassen könntet und nur behaupten müsstet, die Vorsehung wollte das so. Sie würden dann nur davon schwärmen, dass das ein mystisches Omen einer großen Bestimmung war.\n\nKah-Toll ist der Unerträglichste von allen. Ich habe diese Schatzkammer nun eine Weile beobachtet und ich versichere Euch, dass sie sich noch für niemanden geöffnet hat.\n\nWenn sie natürlich geöffnet werden KÖNNTE, würde ich reichlich dafür zahlen, um zu erfahren, was sich darin befindet.", sourceObjective = "Holt Euch eine Belohnung aus der Großen Schatzkammer.", progress = "Vielleicht kann ich Kah-Toll überzeugen, dass die Vorsehung erwartet, dass die Bediensteten eine Woche lang auf ihren Hintern laufen sollten.", completion = "Ihr wart also erfolgreich, wo andere, mich eingeschlossen, gescheitert sind.\n\nVon allem was ich gehört habe, ist das nun das zweite Mal, dass ein Relikt der Ersten auf Eure Anwesenheit reagiert.\n\nIch muss zugeben, dass ich keine Ahnung habe, wie Ihr das geschafft habt. Interessant. Sehr interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[62458] = { id = 62458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Andre Seite", description = "Hey, {name}! Ihr seid genau <der/die:c> richtige {class};!\n\nHier is' Euer alter Kumpel Bwonsamdi, der mit Euch von der Andren Seite aus redet! Ich hab hier 'n kleines Problem mit dem Boss...\n\nIhr seht ziemlich gelangweilt aus, wie Ihr so im Ardenwald rumsteht. Warum kommt Ihr nich' zur Andren Seite und helft 'nem alten Freund? Bwonsamdi verspricht, dass es sich für Euch lohnen wird!\n\nIhr solltet vielleicht noch 'n paar Abenteurer mitbringen... nur für den Fall.", sourceObjective = "Sprecht mit der Maske von Bwonsamdi auf der Andren Seite.", completion = "Hey, Mann! Schön, 'n vertrautes Gesicht zu seh'n. Euer alter Freund Bwonsamdi hat 'n bisschen Ärger mit'm Boss...", sourceObjectiveStatus = "unverified-source-field" }
quests[62459] = { id = 62459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzen überschreiten!", description = "Ah, Ihr kommt gerade recht. Ich habe eine aufregende Entdeckung gemacht.\n\nEs ist mir gelungen, eine Verbindung in einer Entfernung herzustellen, die ich noch nie zuvor erreicht habe.\n\nIhr wollt wissen, wie ich das gemacht habe? Mit harter Arbeit! Aber das wusstet Ihr bereits. Ihr arbeitet fast so hart wie ich. Genau deswegen seid Ihr hier!\n\nSeid Ihr bereit für ein noch aufregenderes Abenteuer?", sourceObjective = "Untersucht das unbekannte Gebiet.", progress = "Ich spüre einen Luftzug auf der anderen Seite. Das wird wohl bedeuten, dass es nicht unterirdisch ist.", completion = "Das sind ganz besondere Motten! Sie beleben diesen Ort ungemein, nicht wahr?\n\nDiese Motten arbeiten genauso hart wie alle anderen, aber keiner schätzt diese Arbeit.\n\nIch danke Euch für ihre Rettung.", sourceObjectiveStatus = "unverified-source-field" }
quests[62461] = { id = 62461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Pirsch im Labyrinth", description = "Sie erschaffen also magische Tiere im Brachland. Ihre Macht ist... enorm.\n\n<Schlundgänger/Schlundgängerin>, ich muss darauf vertrauen, dass Ihr das erledigt. Ich kann Euch Einsicht geben, aber Eure Kampfkraft übersteigt die meine bei weitem.\n\nJagt die Tiere, die auf uns abgerichtet wurden. Zeigt den Schlundgebundenen die Zähne.", sourceObjective = "Schließt eine Jagd im Bestienlabyrinth ab.\n\nEmpfohlene Spieleranzahl [3]", completion = "Ich schätze, das wird nicht Euer letztes Unterfangen im Brachland gewesen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62462] = { id = 62462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Schlüssel der Augen", description = "Ich suche einen Söldner von beispielloser Macht, der das Haus der Augen betritt und den \"Schlüssel der Augen\" beschafft.\n\nDemjenigen, der diesen Schlüssel holt und mir vom Ableben seines vorherigen Besitzers berichtet, wird eine überdurchschnittliche Belohnung geboten.\n\nSeid gewarnt: Das Gelände, das einst zum Haus der Augen gehörte, ist extrem gefährlich und von der alleinigen Erkundung wird dringend abgeraten.", sourceObjective = "Eliminiert Chelicera und beschafft den Schlüssel der Augen.", progress = "Ihr habt also meinen Aushang gesehen?", completion = "Ahh, sehr gut! Und Ihr sagt, eine Million Augen sind erschienen? Wie erschreckend!\n\nGut, dass sie nun fort ist und der Schlüssel in meinen Händen! Sie hat ihn dafür genutzt, viele verschlossene Türen zu öffnen, wisst Ihr? Ein sehr mächtiges Artefakt! Äußerst lukrativ.\n\nUnd jetzt gehört es mir!", sourceObjectiveStatus = "unverified-source-field" }
quests[62465] = { id = 62465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzen überschreiten!", description = "Ah, Ihr kommt gerade recht. Ich habe eine aufregende Entdeckung gemacht.\n\nEs ist mir gelungen, eine Verbindung in einer Entfernung herzustellen, die ich noch nie zuvor erreicht habe.\n\nIhr wollt wissen, wie ich das gemacht habe? Mit harter Arbeit! Aber das wusstet Ihr bereits. Ihr arbeitet fast so hart wie ich. Genau deswegen seid Ihr hier!\n\nSeid Ihr bereit für ein noch aufregenderes Abenteuer?", sourceObjective = "Untersucht das unbekannte Gebiet.", progress = "Ich spüre einen Luftzug auf der anderen Seite. Das wird wohl bedeuten, dass es nicht unterirdisch ist.", completion = "Es ist immer schön, jemandem zur Hand zu gehen, der einfach seine Arbeit macht. Das ist natürlich nur eine Metapher... obwohl es in Eurem Fall doch wörtlich gemeint ist.\n\nIch weiß, was eine Metapher ist!\n\nJedenfalls habt Ihr da draußen gute Arbeit geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[62466] = { id = 62466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzen überschreiten!", description = "Ah, Ihr kommt gerade recht. Ich habe eine aufregende Entdeckung gemacht.\n\nEs ist mir gelungen, eine Verbindung in einer Entfernung herzustellen, die ich noch nie zuvor erreicht habe.\n\nIhr wollt wissen, wie ich das gemacht habe? Mit harter Arbeit! Aber das wusstet Ihr bereits. Ihr arbeitet fast so hart wie ich. Genau deswegen seid Ihr hier!\n\nSeid Ihr bereit für ein noch aufregenderes Abenteuer?", sourceObjective = "Untersucht das unbekannte Gebiet.", completion = "Es muss schön sein, die Zeit zu haben, einfach nur dazusitzen und nachzudenken.\n\nIch selbst habe kaum Zeit. Diesen Ort in Schuss zu halten, ist eine Menge Arbeit!\n\nEs war jedenfalls sehr nett von Euch, der alten Schildkröte zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62467] = { id = 62467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saat eines Gedankens", description = "In den Wildsamen wachsen schlummernd Geister. Doch ersetzen Samen die Geister, können Katalysatoren an ihre Stelle treten.\n\nDie Samenhändlerin Morgengrau handelt mit solchen Samen. Sie kann Euch mit denen versorgen, die Ihr sucht. Wählt einen, den Ihr in einem Wildsamen pflanzen wollt.\n\nDer Wald wartet gespannt auf Eure Entscheidung.", sourceObjective = "Beschafft einen Samen und pflanzt ihn in einen Wildsamen ein.", progress = "Euer Talent als Kultivator entwickelt sich weiter.", completion = "Die erblühenden Äste Eures Könnens strecken sich bis in die Himmel. Das ist gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[62473] = { id = 62473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alt zu neu", description = "Diese verfluchte Geißel macht mich krank!\n\n<Brollen spuckt auf den Boden.>\n\nIhr einziger Nutzen besteht in ihrem Tod!\n\nBegebt Euch zum Tal im Südwesten. Dort gibt es einen Haufen Zeug einzusammeln!\n\nNehmt mit, was Ihr könnt. Ich werde daraus etwas Nützliches erschaffen.", sourceObjective = "Beschafft 8 gezackte Klingen und 8 kampferprobte Kettenpanzer im Großbrand.", progress = "Ihr habt etwas zum Schmelzen gefunden?", completion = "Das sieht doch gut aus.\n\nIch mache mich an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[62477] = { id = 62477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Himmelsschreitergleiter", description = "<Ihr habt den Bauplan für einen Einmalgleiter gefunden, den Dresaelus erfand.\n\nDactylis sollte Euch bei seiner Herstellung behilflich sein können.>", sourceObjective = "Bringt den Bauplan: Himmelsschreitergleiter zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62483] = { id = 62483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Provostenpostbeutel", description = "<Der Beutel ist gut verarbeitet und bietet viel Platz für Schriftrollen und ein Fach, damit Briefe nicht verknittern. Die Stiche sind sauber und der Riemen kann auf die Größe des Trägers eingestellt werden.\n\nIhr seid überzeugt, dass er jedem Provosten gefallen würde.>", sourceObjective = "Ruft Euren Provostbegleiter mit 'Provost beschwören' und übergebt den Provostenpostbeutel.\n\nBereitgestellter Gegenstand:", completion = "Neuer Beutel? Toll! Passt so viel rein!\n\nKann benutzen nicht erwarten. Muss Sika zeigen! Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[62484] = { id = 62484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frisch ans Werk", description = "Vor Kurzem haben wir eine... ungewöhnliche Lieferung erhalten. Ich bin immer noch schockiert.\n\nEin merkwürdiger Flugapparat hat direkt über uns eine riesige Kiste mit Fallschirm abgeworfen. Durch den Wind ist sie ein Stück weiter den Hang hinunter gelandet.\n\nEine Notiz war auch dabei. Wahrscheinlich wäre sie verloren gegangen, hätte man sie nicht an einem schweren Stein befestigt.\n\n<Dunkelreiterin Arly reibt sich eine Stelle an ihrer Stirn.>\n\nIch weiß nicht, was darin ist, aber wenn es uns hilft, dieses Gebiet zu säubern, bin ich dabei.", sourceObjective = "Findet die Kiste. Benutzt das Gerät mit einer rekonstruierten Monstrosität und zerstört dann die Geißeleinheiten in den Fleischwerken.", completion = "Das habe ich nicht erwartet!", sourceObjectiveStatus = "unverified-source-field" }
quests[62486] = { id = 62486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Himmlische Erfrischung", description = "<Ihr habt den Bauplan für einen Tisch mit erfrischenden Leckereien entdeckt, der unterwegs bei Abenteuern recht nützlich sein könnte.\n\nDactylis sollte Euch bei seiner Herstellung behilflich sein können.>", sourceObjective = "Bringt den Bauplan: Himmlische Erfrischung zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62536] = { id = 62536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall Teldrassils", description = "Als ich gehört habe, dass Sylvanas Teldrassil niedergebrannt hat, brach es mir das Herz.\n\nUnd das war nur der Anfang. Wir wissen jetzt, dass die Seelen, die wir an diesem Tag verloren haben, nicht ihren vorbestimmten Ruheplatz einnehmen konnten.\n\nIhr habt die Macht, den Anfang zu machen und dies zu ändern, <Schlundgänger/Schlundgängerin>.\n\nWenn Ihr Euch im Schlund befindet, dann haltet bitte Ausschau nach denen, die wir verloren haben.\n\nBitte, bringt sie heim.", sourceObjective = "Reist in den Schlund und rettet verlorene Seelen.", completion = "Habt Dank, Schlundgänger.\n\nIhr habt ein wenig des Lichts aus der Dunkelheit zurückgeholt.\n\nWir werden dieses Unrecht wiedergutmachen, egal wie lange es dauert.", sourceObjectiveStatus = "unverified-source-field" }
quests[62539] = { id = 62539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stygischer Einäscherer" }
quests[62544] = { id = 62544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein düsterer Ort", description = "Ihr habt schon einmal Nachtelfen aus dem Schlund gerettet. Obwohl die Gefahr immer noch groß ist, muss ich Euch bitten, dies erneut zu tun.\n\nIch muss daran glauben, dass wir sie retten können. So viele wie nur möglich.\n\nVersucht bitte, noch mehr verlorene Seelen zurückzubringen.", sourceObjective = "Reist in den Schlund und rettet verlorene Seelen.", completion = "Ich danke Euch erneut, Schlundgänger.\n\nDiese Seelen sind endlich von Qualen und Schmerz befreit.\n\nEs gibt noch viele mehr, aber ich glaube fest daran, dass wir sie immer noch retten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[62546] = { id = 62546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Irrwisch bleibt zurück", description = "Noch immer siechen viele Kaldoreiseelen im Schlund dahin.\n\n<Schlundgänger/Schlundgängerin>, ich bitte Euch erneut, sie zu finden.\n\nHelft dabei, dieses Unrecht wiedergutzumachen.", sourceObjective = "Reist in den Schlund und rettet verlorene Seelen aus dem Tremaculum und den Ebenen der Qual.", completion = "Es bereitet mir Freude zu sehen, dass noch mehr Seelen aus diesem finsteren Ort gerettet wurden.\n\nIch danke Euch, Schlundgänger, dass Ihr uns weiterhin helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[62549] = { id = 62549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Irrwisch bleibt zurück", description = "Noch immer siechen viele Kaldoreiseelen im Schlund dahin.\n\n<Schlundgänger/Schlundgängerin>, ich bitte Euch erneut, sie zu finden.\n\nHelft dabei, dieses Unrecht wiedergutzumachen.", sourceObjective = "Reist in den Schlund und rettet verlorene Seelen aus dem Tremaculum und den Ebenen der Qual.", completion = "Es bereitet mir Freude zu sehen, dass noch mehr Seelen aus diesem finsteren Ort gerettet wurden.\n\nIch danke Euch, Schlundgänger, dass Ihr uns weiterhin helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[62553] = { id = 62553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzögerte Mühen", description = "Die Geißel nutzt die verseuchte Erde unentwegt, um ihre Kriegswaffen zu erneuern. Wenn wir ihre Arbeiter aufhalten, wird es ihre Produktion verlangsamen. Ein entscheidender Schlag gegen ihre Vorräte wäre allerdings noch effizienter.\n\nNehmt das hier und geht in das Gebiet südöstlich von hier. Platziert die Bomben und macht Euch dann schnell aus dem Staub.\n\nWenn wir ihre Versorgungsline schwächen, verschaffen wir uns Zeit für einen Gegenschlag.", sourceObjective = "Platziert die Bomben an den nördlichen, östlichen und westlichen Stellen des Bombardements. Entfernt 12 klapprige Arbeiter aus dem Gebiet.", completion = "Wir danken Euch für Euer Engagement in der Sache, {name}. Ihr habt erneut Euer Leben riskiert, um die Sicherheit unserer Verbündeten zu gewährleisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[62554] = { id = 62554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todschlicker Hut: Rote Kopfkerze", progress = "Eine meiner Kopfkerzen wird sie locker alle beeindrucken, stimmt's?", completion = "Das nenne ich mal richtig passend!" }
quests[62555] = { id = 62555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berührung der Demut", description = "Da der Tempel der Demut nun unter unserer Kontrolle ist, wird seine Macht wieder zurück in das Emblem des Aufstiegs fließen.\n\nTrefft mich unten, damit wir es zusammen betrachten können. Mikanikos hat versprochen, dass es noch prachtvoller sein wird, je mehr seine Macht anwächst.", sourceObjective = "Seht zu, wie das Emblem des Aufstiegs durch den Tempel der Demut ermächtigt wird.", completion = "Die Archon wird die Paragons versammeln und mit ihnen unsere nächsten Schritte erörtern. Geht und dient.", sourceObjectiveStatus = "unverified-source-field" }
quests[62556] = { id = 62556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todschlicker Hut: Festlicher rosa Hut", progress = "Dieser festliche rosa Hut ist der absolute Knaller!", completion = "Das nenne ich mal richtig passend!" }
quests[62557] = { id = 62557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Reich in unseren Händen", description = "Es gibt zwar in der ganzen Bastion noch kämpfende Verschmähte, aber der Tempel der Loyalität ist unser und somit auch unser Reich.\n\nWir müssen strategisch vorgehen, damit alle Tempel weiter in unserer Hand bleiben, und viel hängt auch davon ab, welches Schicksal unsere Gefallenen ereilt, aber das heute war ein großer Sieg für uns.\n\nTrefft mich am Emblem des Aufstiegs und seht die letzte Ermächtigung.", sourceObjective = "Seht zu, wie das Emblem des Aufstiegs durch den Tempel der Loyalität ermächtigt wird.", completion = "Diesen Sieg hätten wir ohne Euch nicht errungen, Schlundgänger.\n\nDie Archon, die Paragons und alle Kyrianer danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[62558] = { id = 62558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todschlicker Hut: Faefestmaske", progress = "Ich muss so eine Faefestmaske haben. So bleib ich ganz mysteriös und alle müssen raten, wer ich bin.", completion = "Das nenne ich mal richtig passend!" }
quests[62559] = { id = 62559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todschlicker Hut: Krone des Rechtschaffenen", progress = "Ich weiß, was ich brauch! Alle werden wird sich vor mir verbeugen, wenn die mich mit 'ner Krone des Rechtschaffenen sehen.", completion = "Das nenne ich mal richtig passend!" }
quests[62560] = { id = 62560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zunehmende Macht", description = "Wunderbare Neuigkeiten, {name}!\n\nIhr habt genug Anima gesammelt, damit die Königin das Herz des Waldes jetzt ermächtigen kann!", sourceObjective = "Seht zu, wie die Winterkönigin das Herz des Waldes ermächtigt.", completion = "Wir sind auf dem richtigen Weg, {name}! Macht weiter so und es wird bald wieder in seiner vollen, glorreichen Strahlkraft erleuchten!", sourceObjectiveStatus = "unverified-source-field" }
quests[62561] = { id = 62561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Herz ist voll", description = "{name}! Ist das zu fassen! Wir haben genug Anima gesammelt, dass die Winterkönigin das Herz des Waldes wiederherstellen kann!\n\nIhr habt so viel für uns getan!", sourceObjective = "Seht zu, wie die Winterkönigin das Herz des Waldes ermächtigt.", completion = "Wir danken Euch für Eure Hilfe, {name}. Das Herz des Waldes wieder so mächtig zu sehen... Mein Herz pocht laut vor Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[62563] = { id = 62563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder da!", description = "Gorgantus gibt einfach nicht auf!\n\nWir haben sie schon einige Male besiegt, aber die Plünderer holen ihre Überreste, flicken sie wieder zusammen und schicken sie geradewegs wieder gegen uns!\n\nSie denkt, dass sie uns dieses Mal besiegen wird... Beweist ihr das Gegenteil.", sourceObjective = "Tötet Gorgantus die Ausweiderin.", completion = "Bei Euch hat das so leicht ausgesehen. Hoffen wir, dass sie dieses Mal ihre Lektion gelernt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[62567] = { id = 62567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Chromies Aufruf", description = "Chromie sucht nach erfahrenen Abenteurern, die sich auf eine Reise durch Raum und Zeit begeben wollen.\n\nDas ist Eure Chance, die legendären Abenteuer der Vergangenheit hautnah mitzuerleben, und zwar heute!\n\nSprecht mit Chromie in der Nähe der Botschaft von Sturmwind, um mehr zu erfahren.", sourceObjective = "Sprecht mit Chromie in Sturmwind.", completion = "Ich bin froh, dass Ihr es geschafft habt, {name}! Ich habe das Gefühl, dass Eure Zukunft in der Vergangenheit wartet!", sourceObjectiveStatus = "unverified-source-field" }
quests[62568] = { id = 62568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Chromies Aufruf", description = "Chromie sucht nach erfahrenen Abenteurern, die sich auf eine Reise durch Raum und Zeit begeben wollen.\n\nDas ist Eure Chance die legendären Abenteuer der Vergangenheit hautnah mitzuerleben, und zwar heute!\n\nSprecht mit Chromie in der Nähe der Botschaft von Orgrimmar, um mehr zu erfahren.", sourceObjective = "Sprecht mit Chromie in Orgrimmar.", completion = "Ich bin froh, dass Ihr es geschafft habt, {name}! Ich habe das Gefühl, dass Eure Zukunft in der Vergangenheit wartet!", sourceObjectiveStatus = "unverified-source-field" }
quests[62569] = { id = 62569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Griff des Kerkermeisters", description = "Mit dem Blick in den Schlund hat Bolvar die Aufmerksamkeit des Kerkermeisters auf sich gezogen.\n\nSeine schlimmsten Befürchtungen haben sich bewahrheitet.\n\nIhr müsst mir helfen, die Verbindung zu unterbrechen, {name}! Das Helmfragment ist der Schlüssel!", sourceObjective = "Helft Jaina Prachtmeer, die Verbindung des Kerkermeisters zu Bolvar zu trennen.", completion = "Der Kerkermeister... ist aus meinem Kopf... verschwunden.\n\nDanke, {name}. Ihr habt mich vor einem dunkleren Schicksal bewahrt, als Ihr jemals ahnen könnt.\n\nDafür werde ich Euch ewig dankbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62579] = { id = 62579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venari Rep Token Tracking" }
quests[62584] = { id = 62584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frontversorgung", description = "Dieses Vorhutslager ist extrem abhängig von der Versorgungslinie zum Turnierplatz. Kürzlich wurde eine Lieferung bei der Durchquerung des Tals unter uns überfallen.\n\nBergt soviel Ihr könnt und beseitigt die Gefahren, die dort lauern. Das soll uns nicht noch einmal passieren.", sourceObjective = "Beschafft 6 geborgene Güter und tötet 3 elende Beobachter im Tal der Gefallenen Helden.", progress = "Gefangen in der Eiswüste, kalt und einsam... Ich hoffe nur, dass unsere Verbündeten erbittert Widerstand leisten.\n\n<Kreuzfahrerin Renn schüttelt ihren Kopf.>\n\nKonntet Ihr Teile der Lieferung bergen?", completion = "Ich danke Euch, für Euer rasches Eingreifen, {name}.\n\nDiese Güter sollten uns bis zur nächsten Lieferung versorgen.\n\nIch kümmere mich darum, dass die Körper unserer Gefallenen geborgen und nach unseren Riten bestattet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[62587] = { id = 62587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach innerer Ruhe", description = "Ich habe schon immer Träume gehabt.\n\nBesondere Träume, könnte man sagen.\n\nIm Traum kann mir jeder Ort der Ruhe oder Stille erscheinen.\n\nSogar jene, denen Gefahr drohen könnte, denn Ruhe ist überall zu finden, wenn man weiß, wie.\n\nJetzt träume ich von Eurer Welt, Eurem Azeroth.\n\nIch kann nicht in Euer Reich reisen. Helft mir, mich durch Eure Augen mit meinem neuesten Traum zu verbinden.\n\nIch träume von einem hochgelegenen Ort. Einem sehr hochgelegenen Ort. Kennt Ihr ihn?", sourceObjective = "Reist zum Hochberg auf der Suche nach Ruhe.", progress = "Kehrt nach Eurem Besuch des Orts, den ich in meinem Traum gesehen habe, zu mir zurück.", completion = "Das war ein so angenehmer Traum. Ich freue mich, dass Ihr die Realität erleben durftet.", sourceObjectiveStatus = "unverified-source-field" }
quests[62588] = { id = 62588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach innerer Ruhe", description = "Ihr kehrt zurück.\n\nDas gefällt mir.\n\nWeitere Orte der Ruhe sind mir im Traum erschienen.\n\nIch sehe einen Sandstrand, Sonnenuntergänge.\n\nIch kann nicht in Euer Reich reisen. Helft mir, mich durch Eure Augen mit meinem neuesten Traum zu verbinden.", sourceObjective = "Reist nach Zuldazar, um zu meditieren.", completion = "Das war ein so angenehmer Traum. Ich freue mich, dass Ihr die Realität erleben durftet.", sourceObjectiveStatus = "unverified-source-field" }
quests[62589] = { id = 62589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach innerer Ruhe", description = "Ich freue mich, dass Ihr Eure Meditationen fortsetzen möchtet.\n\nEs wird Euch helfen, Eure Mitte zu finden.\n\nIch hatte noch einen Traum, einen warmen Traum von einem kalten Ort.\n\nEr ist in Weiß gehüllt. Wisst Ihr davon?\n\nBegebt Euch dorthin und erlebt die Aussicht, die ich in meinem Traum gesehen habe.", sourceObjective = "Meditiert in Winterquell.", completion = "Das war ein so angenehmer Traum. Ich freue mich, dass Ihr die Realität erleben durftet.", sourceObjectiveStatus = "unverified-source-field" }
quests[62590] = { id = 62590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach innerer Ruhe", description = "Danke für Eure Rückkehr.\n\nIch hatte einen weiteren Traum. Eine weitere Vision von Eurem Reich.\n\nIn diesem Traum tanzte der Himmel über mir.\n\nAm Rande einer Klippe, in einem nördlichen Land.\n\nWelch ein unvergesslicher Anblick.\n\nIhr müsst es selbst erleben.", sourceObjective = "Meditiert am Heulenden Fjord.", completion = "Das war ein so angenehmer Traum. Ich freue mich, dass Ihr die Realität erleben durftet.", sourceObjectiveStatus = "unverified-source-field" }
quests[62591] = { id = 62591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach innerer Ruhe", description = "Wir haben schon so viel gemeinsam erlebt.\n\nIch bin dankbar, einen Begleiter auf dieser Entdeckungsreise zu haben.\n\nIhr wandelt dort, wo ich nur projizieren kann.\n\nIhr berührt das, was ich nur sehen kann.\n\nIch hatte einen weiteren Traum.\n\nEine andere Küste. Eine Statue.\n\nEine große Statue eines kleinen Wesens.\n\nGeht und sucht den Anblick aus meinem Traum.", sourceObjective = "Meditiert in Beutebucht.", completion = "Das war ein so angenehmer Traum. Ich freue mich, dass Ihr die Realität erleben durftet.", sourceObjectiveStatus = "unverified-source-field" }
quests[62592] = { id = 62592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der inneren Ruhe", description = "Ihr habt einen weiten Weg zurückgelegt.\n\nIhr seid fast bereit, Eure innere Ruhe an jedem beliebigen Ort zu finden.\n\nNur noch eine Reise unter meiner Führung.\n\nSie ist kurz. In diesem Garten hat schon immer Frieden geherrscht.\n\nEs gibt noch einen Ort der Ruhe zu erleben.\n\nDanach werdet Ihr Eure geistigen Fesseln abstreifen. \n\nIch werde stolz sein.", sourceObjective = "Findet den neuen Meditationsort im Konservatorium der Königin.", completion = "Das war ein so angenehmer Traum. Ich freue mich, dass Ihr die Realität erleben durftet.", sourceObjectiveStatus = "unverified-source-field" }
quests[62593] = { id = 62593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd: Todeselementare" }
quests[62597] = { id = 62597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenschmiedin Heirmir", description = "<Alexandros Mograine hat Euch ein sehr eindeutiges Empfehlungsschreiben für eine gewisse Knochenschmiedin Heirmir in Maldraxxus hinterlassen.\n\nWelche Hilfe könnte sie dem Gluthof anbieten?>", sourceObjective = "Bringt den Brief von Alexandros Mograine zu Knochenschmiedin Heirmir in Maldraxxus.\n\nBereitgestellter Gegenstand:", completion = "Was wollt Ihr, Schlundgänger?", sourceObjectiveStatus = "unverified-source-field" }
quests[62598] = { id = 62598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedin Sophone", description = "<Polemarch Adrestes hat Euch ein sehr förmliches Empfehlungsschreiben für eine gewisse Schmiedin Sophone in der Bastion hinterlassen.\n\nWelche Hilfe könnte sie dem Gluthof anbieten?>", sourceObjective = "Bringt den Brief von Polemarch Adrestes zu Schmiedin Sophone in der Bastion.\n\nBereitgestellter Gegenstand:", completion = "Ich nehme an, Ihr benötigt meine Hilfe, Schlundgänger. Was kann ich für Euch tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[62599] = { id = 62599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormschmied Cavina", description = "<Jagdhauptmann Korayn hat Euch ein knappes Empfehlungsschreiben für einen gewissen Gormschmied Cavina im Ardenwald hinterlassen.\n\nWelche Hilfe könnte er dem Gluthof anbieten?>", sourceObjective = "Bringt den Brief von Jagdhauptmann Korayn zu Gormschmied Cavina im Ardenwald.\n\nBereitgestellter Gegenstand:", completion = "Benötigt Ihr eine Rüstungsreparatur?", sourceObjectiveStatus = "unverified-source-field" }
quests[62600] = { id = 62600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inneren Frieden finden", description = "Dies ist ein wunderschöner Ort, findet Ihr nicht?\n\nIch kannte die Mythen des Ardenwalds.\n\nHab ihn sogar flüchtig im Traum erblickt.\n\nUnd doch ist er erfüllt mit ungeahnter Ruhe.\n\nRuhe ist das, wofür meinesgleichen leben. Sogar im Chaos.\n\nMan kann immer Ruhe finden. Soll ich es Euch zeigen? \n\nIch spüre eine Konvergenz der Ruhe ganz in der Nähe. Das wird eine geeignete Demonstration sein.", sourceObjective = "Reist hinaus in den Ardenwald, um mit der Ruhe des Landes Zwiesprache zu halten.", completion = "Versteht Ihr jetzt? Es liegt eine große Kraft darin, Ruhe zu finden. Die Fähigkeit, seine innere Mitte zu finden, spendet selbst in den turbulentesten Zeiten Trost.", sourceObjectiveStatus = "unverified-source-field" }
quests[62601] = { id = 62601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedi", description = "<Rendel hat Euch einen zerknitterten Umschlag hinterlassen, der an Schmiedi in Dunkelhafen adressiert ist. Auf der Außenseite des Umschlags befinden sich sehr genaue Anweisungen, Schmiedi mitzuteilen, dass Rendel Euch geschickt hat.\n\nWelche Hilfe könnte Schmiedi dem Gluthof anbieten?>", sourceObjective = "Bringt Rendels Brief zu Schmiedi in Dunkelhafen.\n\nBereitgestellter Gegenstand:", completion = "Was kann ich für Euch tun, Schlundgänger?", sourceObjectiveStatus = "unverified-source-field" }
quests[62603] = { id = 62603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltener und ungewöhnlicher Geist", description = "Schön, Euch wiederzusehen, <Freund/Freundin>!\n\nWir haben noch einen reglosen Geist gefunden, der von dunklen Träumen ergriffen ist. Schlimme Sache! \n\nIn diesem Traum wird eine noble Figur, einst Vorbild der Treue, von Selbstzweifeln zerfressen und auf einen dunklen Pfad geführt.\n\nWenn Ihr den gefallenen Paragon besiegen würdet, könnten wir den armen Geist sicher wiederbeleben.\n\nHelft Ihr uns noch einmal, {name}?", sourceObjective = "Besiegt Devos in den Spitzen des Aufstiegs.", completion = "Noch eine erfüllte Traumvision. Bemerkenswert.", sourceObjectiveStatus = "unverified-source-field" }
quests[62605] = { id = 62605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mittlergeschäfte", description = "<Eine von Spinnennetzen überzogene Kiste mit diversem Gelehrtenzubehör steht zufällig auf dem Boden. Sie scheint von einem Mittler hergestellt worden zu sein. Vielleicht ist der Besitzer in der Nähe.>", sourceObjective = "Findet den Besitzer des vergessenen Zubehörs.", completion = "Oh! Mein gestohlenes Zubehör! Welch ein Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[62606] = { id = 62606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzdornmischung", description = "Ah, genau <der Pilzomant, den/die Pilzomantin> die; ich sehen wollte! Macht es Euch etwas aus, mir etwas Lehm zu besorgen?\n\nEs gibt alle möglichen Arten von Erde, müsst Ihr wissen. Es ist nicht alles nur Dreck! Und Lehm... Lehm ist etwas Besonderes. Habt Ihr jemals versucht, durch Lehm hindurchzuwachsen? Oh, ich schätze nicht.\n\nDer Durchbruch ist harte Arbeit, aber wenn man es einmal geschafft hat, ist der Geschmack unvergleichlich! Meine Wurzeln freuen sich auf die Herausforderung.\n\nDer Schwarzdornhain hat einen besonders bitteren und vielschichtigen Lehm, und genau nach diesem sehne ich mich. Ich bin sicher, sie werden nichts dagegen haben, wenn Ihr sie um etwas davon bittet.", sourceObjective = "Sammelt 6 Brocken Schwarzdornlehm im Schwarzdornhain.", progress = "Wenn sie Euch Schwierigkeiten machen, sagt ihnen einfach, Marasmius schickt Euch. Ich wette, irgendjemand dort ist alt genug, um sich an mich zu erinnern.", completion = "Ooh, das ist genau das richtige Zeug. Es ist zwar bitter, aber wunderbar vielschichtig und mit subtilen Untertönen. Mhm! Irgendwann müsst Ihr ihn mal probieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[62607] = { id = 62607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glitzernde grobe Güte", description = "Einen wunderschönen guten Tag! Hättet Ihr Lust, mir heute etwas auszuhelfen?\n\nSeid Ihr schon mal in Schimmergeäst gewesen? Habt Ihr Euch jemals gefragt, warum der Ort so heißt? Ich war dort, als er seinen Namen bekam, müsst Ihr wissen.\n\nViele Leute denken, es liegt an den Bäumen oder am Wasser, und sie haben recht. Aber das Geheimnis des Schimmerns liegt im Schlick. Der Boden saugt sich voll und gewinnt überschüssige Anima aus dem Wasser, bis der Boden förmlich funkelt.\n\nIch könnte jetzt wirklich etwas Schimmerschlick vertragen. Würdet Ihr einen alten Pilz wieder in seine Jugend zurückversetzen?", sourceObjective = "Sammelt 6 Einheiten Schimmerschlick in Schimmergeäst.", progress = "Oooh, ich hatte immer ein Kribbeln am ganzen Körper, wenn ich Schimmerschlick hatte. Und das ist eine Menge Kribbeln!", completion = "Seht nur, wie er funkelt und glänzt! Ich bekomme schon beim bloßen Anblick ein Kribbeln. Ich fühle mich jetzt schon Jahre jünger!", sourceObjectiveStatus = "unverified-source-field" }
quests[62608] = { id = 62608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine königliche Leckerei", description = "Es ist so schön, Euch wiederzusehen. Ich habe eine besondere Bitte an Euch.\n\nDie Winterkönigin höchstpersönlich hat in den frühen Zeiten die Haine gepflegt. Alles, was sie berührt hat, strotzte vor Leben und Kraft. Sogar der Boden, auf dem sie gewandelt ist.\n\nIm Laufe der Zeit wurde der Garten der Königin als Garten der Nacht bekannt, denn die Königin hatte sich so lange nicht um ihren Garten gekümmert.\n\nAber im Boden ruht noch immer ihre Kraft. Er ist die beste Mahlzeit, die ich je hatte. Ich weiß, das ist dekadent, aber wir wissen beide, dass ich es verdiene!", sourceObjective = "Sammelt 6 Stücke königlichen Torf im Garten der Nacht.", progress = "Manchmal muss man sich einfach etwas Schönes gönnen.", completion = "Fühlt Ihr, wie luxuriös der Boden ist? Ich werde ihn noch eine ganze Weile genießen. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[62609] = { id = 62609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arsenal der Nekrolords", description = "<Ihr gebt Knochenschmiedin Heimir den Brief, und sie beginnt zu lesen.>\n\nHmm. Normalerweise ist Mograine vernünftiger...\n\n<Nachdem Knochenschmiedin Heimir den Brief gelesen hat, zerreißt sie ihn mit ihren knochigen Fingern.>\n\nEin Befehl ist ein Befehl. Ich lasse eine Lieferung Rohmaterial und Schmiedeausrüstung zu Eurem Hof bringen.\n\nMograine bittet darum, dass Ihr, während Ihr wartet, einige unserer Feinde beseitigt, um für meine Abwesenheit vorzusorgen.\n\nEs stand in dem Brief. Schade, dass er so zerfetzt ist und Ihr ihn nicht lesen könnt.", sourceObjective = "Schließt Weltquests in Maldraxxus ab.", completion = "Gut. Ich habe auf unserer Seite alles Nötige arrangiert,.\n\nIch werde da sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62610] = { id = 62610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilzpatrouille: Die Stiele", description = "<Marasmius seufzt.>\n\nEs geht wieder los, oben in den Stielen.\n\nEs scheint, als hätten wir ihnen beim ersten Mal nicht genug Prügel verpasst, eh? Wie wär's, wenn wir beide uns wieder zusammentun und diesen Jünglingen eine Lektion erteilen, die sie nicht vergessen werden?\n\nSagt mir Bescheid, wenn Ihr bereit seid, und wir kriegen sie, genau wie vorher!", sourceObjective = "Reist durch die Faeringe und tötet 30 maskierte Eindringlinge in den Stielen.", completion = "Hmpf, geschieht ihnen recht. Sie glauben, sie können in meinem Hain herumtrampeln? Ich bin der Einzige, der hier herumtrampeln darf! Ich bin derjenige, der trampelt!", sourceObjectiveStatus = "unverified-source-field" }
quests[62611] = { id = 62611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilzpatrouille: Herzholzhain", description = "Diese maskierten Unholde haben den Herzholzhain übernommen, und ich gedenke, ihre Pläne zu durchkreuzen.\n\nDer Herzholzhain war vorher so schön. Und jetzt ist er... Egal. Wir werden das in Ordnung bringen, Ihr und ich. Jetzt sofort.\n\nKommt, schließt Euch mir im Kampf an. Wir werden diesen Monstern eine Tracht Prügel verpassen, sodass ihre Meister es sich zweimal überlegen werden, bevor sie diesen heiligen Ort wieder entweihen!", sourceObjective = "Reist durch die Faeringe und tötet 30 besessene Schänder im Herzholzhain.", completion = "So, das wär's. Wir sollten sie vertrieben haben, wenn auch nur für eine Weile. Ich weiß die Hilfe zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62612] = { id = 62612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arsenal der Venthyr", description = "<Ihr gebt Schmiedi den Brief, der ihn sofort liest.>\n\nAh, Rendel schickt Euch. Hättet Ihr auch gleich sagen können.\n\nKein Problem. Ich besorge Euch alles, was Ihr braucht, um an dem Hof Schädel einzuschlagen.\n\nWerde wohl etwas Hilfe brauchen, um meinen Boss davon zu überzeugen, mir freizugeben.\n\nGanz schön lästig, oder?\n\nSagen wir, Ihr kümmert Euch um einige der Ärgernisse hier und erzählt allen, dass Ihr es für mich tut. Das dürfte reichen.", sourceObjective = "Schließt Weltquests in Revendreth ab.", completion = "Gute Arbeit. Der Boss hat mir freigegeben.\n\nWir treffen uns dort, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[62613] = { id = 62613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arsenal der Kyrianer", description = "<Ihr gebt Schmiedin Sophone den Brief, die ihn sofort liest.>\n\nIch verstehe.\n\nWo immer ich dienen kann, dort werde ich hingehen.\n\nSeid Ihr bereit, dasselbe zu tun? Werdet Ihr der Bastion dort dienen, wo es nötig ist?", sourceObjective = "Schließt Weltquests in der Bastion ab.", completion = "Mein Hammer gehört Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[62614] = { id = 62614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilzpatrouille: Abendhain", description = "Ich hoffe, Ihr seid bereit zu kämpfen.\n\nDie Drust verstärken ihre Kräfte im Abendhain. Die meisten im Ardenwald erinnern sich nicht an sie, aber ich schon. Man muss sie vollständig ausrotten, um sie loszuwerden, sonst wachsen sie wieder nach und sind zäher als je zuvor.\n\nKommt mit. Wir werden sie bis auf den Letzten ausradieren. Sagt mir Bescheid, wenn Ihr soweit seid.", sourceObjective = "Reist durch die Faeringe und tötet 30 besessene Eindringlinge im Abendhain.", progress = "Schnell, bevor sie sich noch weiter im Ardenwald ausbreiten. Jetzt ist unsere Chance.", completion = "Gute Arbeit. Sie verschanzen sich immer noch im Dunkelvorstoß, aber mehr können wir vorerst nicht tun. Wir halten sie unter Kontrolle und dann räuchern wir sie aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[62615] = { id = 62615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilzpatrouille: Gespinstklippen", description = "Schlechte Nachrichten von den Gespinstklippen. Wir müssen helfen.\n\nDie Schurken, die die armen Seidenschreiter terrorisieren, sind in letzter Zeit grausamer und aggressiver geworden. Die Seidenschreiter sind wichtig für den Ardenwald, wichtiger als die meisten wissen. Wir dürfen nicht noch mehr verlieren.\n\nSagt mir Bescheid, wenn Ihr bereit seid, und wir werden diese Racker für immer verscheuchen!", sourceObjective = "Reist durch die Faeringe und tötet 30 Schwarzdornangreifer an den Gespinstklippen.", completion = "Die kleinen Fräuleins sollten vorerst sicher sein. Ihr Zweck ist für den Ardenwald lebenswichtig, und ich will nicht, dass noch mehr von ihnen unter meiner Aufsicht sterben!", sourceObjectiveStatus = "unverified-source-field" }
quests[62616] = { id = 62616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arsenal der Nachtfae", description = "<Ihr gebt den Brief Gormschmied Cavina, der ihn sofort liest.>\n\nEs überrascht mich nicht, dass der Jagdhauptmann Euch zu mir geschickt hat. Ich bin schließlich der beste Gormschmied im ganzen Ardenwald.\n\nIhre Befehle sind eindeutig und ich helfe gerne.\n\nIhr müsst für uns ein paar zusätzliche Patrouillen übernehmen, um die verlorene Zeit und die verlorenen Ressourcen auszugleichen.\n\nKlingt das fair?", sourceObjective = "Schließt Weltquests im Ardenwald ab.", completion = "Alles ist bereit. Ich freue mich auf das Abenteuer.", sourceObjectiveStatus = "unverified-source-field" }
quests[62618] = { id = 62618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Odalrik" }
quests[62619] = { id = 62619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine abschweifende Geschichte", description = "<Ein flüchtiger Blick in den schweren Folianten verrät eine blumige Sprache und einen ziellosen Handlungsstrang. Zumindest in den ersten paar Kapiteln.\n\nDer Einband ist etwas schmutzig, aber der Schaden ist nicht zu groß. Dieses Buch hat noch nicht viele Abenteuer gesehen - fast so wie seine Handlung.\n\nArchivar Dreyden hätte dieses Buch sicher gerne zurück.>", sourceObjective = "Bringt die mäandernde Geschichte zu Archivar Dreyden im Hain der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Oh! Ihr habt eines meiner Bücher gefunden! Ich danke Euch von ganzem Herzen für seine Wiederbeschaffung.", sourceObjectiveStatus = "unverified-source-field" }
quests[62620] = { id = 62620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Wandererzählung", description = "<Dieses Buch bietet zwar eine zielgerichtete Geschichte, aber der Autor schwelgt in allen möglichen Windungen und Abschweifungen. Vielleicht geht es aber auch nur um den Weg und nicht das Ziel...\n\nZumindest würde sich Archivar Dreyden sicher freuen, sein Buch zurückzubekommen.>", sourceObjective = "Bringt die abschweifende Erzählung zu Archivar Dreyden im Hain der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Ich habe gerade über dieses Buch nachgedacht! Ich hatte gehofft, es findet alleine zurück. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[62621] = { id = 62621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein eskapistischer Roman", description = "<Kampf, Abenteuer, Aufregung, Gänsehaut... dieses Buch bietet alles! Verfasst von einem Sterblichen, der ein aufregendes Leben hatte. Was für ein fesselndes Buch. \n\nIst es realistisch? Eine Person bekämpft in einem einzigen Leben Verschwörungen, uralte Schrecken, riesige Armeen, Dämonen und sogar Götter?\n\nGenau genommen könnte es sogar stimmen, aber von welcher \"Ente\" ist andauernd die Rede? Das klingt unrealistisch.\n\nTrotzdem eine tolle Geschichte. Archivar Dreyden wird froh sein, sein Buch zurückzubekommen.>", sourceObjective = "Bringt den eskapistischen Roman zu Archivar Dreyden im Hain der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Eine tolle Geschichte! Ich hoffe, dem Autor geht es gut in diesen schweren Zeiten! Welch ein Glück. Ich danke Euch für seine Wiederbeschaffung.", sourceObjectiveStatus = "unverified-source-field" }
quests[62622] = { id = 62622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Reisetagebuch", description = "<Dieses Buch scheint ein persönliches Reisetagebuch über Ardenwald zu sein! Eigenhändig geschrieben und veröffentlicht!\n\nAls Ihr das Ende durchblättert, kommt Ihr Euch vor wie ein Bösewicht, der das Buch ungerechtfertigt angreift und öffnet.\n\nIhr lest die Zeilen \"Dieses Buch scheint ein persönliches Reisetagebuch über Ardenwald-\"\n\nIhr fühlt Euch unwohl und schließt das Buch schnell wieder. Archivar Dreyden sollte es wiederbekommen.>", sourceObjective = "Bringt das Reisetagebuch zu Archivar Dreyden im Hain der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Es hat sich selbst geschrieben? Wie faszinierend! Das Rekursionsgefühl wird wieder verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[62623] = { id = 62623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schlüpfrige Geschichte", description = "<Ihr habt dieses Buch noch nicht einmal fünf Minuten in der Hand gehalten und es ist Euch schon ein Mal entwischt, hat Euch zwei Mal gebissen und irgendwie sogar Euer Gold geklaut.\n\nDas hattet Ihr nicht von dem frechen Schwank erwartet, allerdings hätte man es sich denken können.\n\nIhr schließt das Buch und umwickelt es, dass es nicht noch mehr Schaden anrichtet. Es wird Zeit, es Archivar Dreyden zu bringen.>", sourceObjective = "Bringt den frechen Schwank zu Archivar Dreyden im Hain der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt eines meiner Bücher gefunden!\n\nOh. Dieses Werk.\n\n<Dreyden seufzt.>\n\nIch denke, ich nehme es zurück. Danke, oder so ähnlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[62624] = { id = 62624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Konservatorium der Königin", description = "Ich habe gehört, dass Ihr uns bei der Wiederherstellung unseres Sanktums unterstützen wollt, {name}.\n\nEs gibt einen ganz besonderen magischen Hain, der bei uns das Konservatorium der Königin genannt wird.\n\nIn diesem magischen Sanktum pflegen wir die Geister alter Gottheiten, um sie wieder zum Leben zu erwecken. Aber seine Magie hat mit der Animadürre nachgelassen.\n\nEr ist auf Eure Hilfe angewiesen.\n\nEs würde uns viel bedeuten, wenn Ihr den Wiederherstellungsprozess einleiten könntet, indem Ihr die von uns benötigten Ressourcen beschafft.", sourceObjective = "Sprecht mit Zayhad, um das Konservatorium der Königin freizuschalten.", progress = "Nachdem Ihr ausreichend Ressourcen gesammelt habt, könnt Ihr in Euer Sanktum gehen und mit Zayhad sprechen, um das Konservatorium der Königin freizuschalten.", completion = "Ich bin so froh, dass Ihr begonnen habt, dem Konservatorium der Königin wieder zu seinem früheren Glanz zu verhelfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62625] = { id = 62625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltener und ungewöhnlicher Geist", description = "Den Fortschritt zu sehen, den Ihr bei der Wiederherstellung des Konservatoriums gemacht habt, ist höchst erfreulich, {name}!\n\nDoch noch sind wir nicht fertig.\n\nWir haben noch einen reglosen Geist gefunden, den ein dunkler Traum am Erwachen hindert.\n\nIn diesem Traum ist der Geist inmitten einer Fehde zwischen alten Wesen gefangen. Beide Seiten sind nicht frei von Makel, doch die eine ist viel schlimmer als die andere!\n\nWenn Ihr den Vater des Schlafs besiegt, sollte der Geist von seinem Schlummer befreit werden. Werdet Ihr helfen?", sourceObjective = "Besiegt Mueh'zala auf der Andren Seite.", completion = "Noch eine erfüllte Traumvision. Bemerkenswert.", sourceObjectiveStatus = "unverified-source-field" }
quests[62626] = { id = 62626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mullbys Marke", description = "Es sieht so aus, als könnte diese Marke diesem Mulby etwas bedeuten. Wenn Ihr sie ihm in Maldraxxus bringt, springt vielleicht eine Belohnung raus.", sourceObjective = "Bringt die Marke zur Herausfordererpromenade in Maldraxxus.", completion = "Ihr habt etwas für mich? Wundervoll! \n\n<Mit leiserer Stimme.> \n\nWie habt Ihr das gefunden? Natürlich werde ich Euch für seine Rückkehr belohnen, Großmeister Vole hätte seinen Verlust niemals akzeptiert und mich komplett ausgequetscht. Ihr habt keine Ahnung, wovor Ihr mich da bewahrt habt.\n\nOh, und bitte erwähnt das nicht vor Elsa. Sie würde mir das ewig vorhalten. Ich verspreche, dass ich dem Glücksspiel abschwören werde! Ab heute!", sourceObjectiveStatus = "unverified-source-field" }
quests[62627] = { id = 62627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle Geister, groß und klein", description = "Dies ist ein höchst merkwürdiger Ort.\n\nSo viel Energie der Wiedergeburt. Eine Verschmelzung verschiedener Formen von Magie. Nicht das, was ich erwartet hatte.\n\nAuch ich war von meinesgleichen zur Wiedergeburt vorgesehen. Diese Magie ist mir bekannt und dennoch wie nichts, was ich bisher gesehen habe. Und doch dient alles dem Gleichgewicht.\n\nNicht nur große und bedeutende Geister helfen, das kosmische Gleichgewicht aufrechtzuerhalten.\n\nAuch die kleinsten Geschöpfe können eine Rolle spielen.\n\nSoll ich es Euch zeigen? Besucht die Überreste eines solchen Geschöpfes, und wir werden seinen Geist neu beleben.", sourceObjective = "Reist auf der Suche nach den Überresten zum Frostfeuergrat.", completion = "Ihr habt sie schon gesehen? Ja, das habt Ihr. Ich kann das erkennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62628] = { id = 62628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voles Gutschein", description = "<Dieser Gutschein enthält alle Informationen. Bringt diesen Gutschein Au'narim auf der Herausfordererpromenade vor dem Theater der Schmerzen in Maldraxxus. Er sollte Euch das Geld aus dem Kredit von Großmeister Vole auszahlen.>", sourceObjective = "Bringt den Gutschein zur Herausfordererpromenade in Maldraxxus.", progress = "Wollt Ihr eine Transaktion veranlassen?", completion = "<Au'narim nimmt Euren Gutschein und studiert ihn.>\n\nGutschein beurkundet. Auszahlung der Mittel genehmigt. Bitte beehrt uns wieder, wenn Ihr eine weitere Transaktion tätigen möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[62629] = { id = 62629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle Geister, groß und klein", description = "Es ist Zeit für uns, einen weiteren Tiergeist wiederzubeleben.\n\nDieser ist durch Feuer und Überfälle in einem fernen Land ums Leben gekommen.\n\nGeht. Haltet mit den Überresten der Kreatur Zwiesprache. Lasst ihren Geist frei, damit er hierher zurückkehren kann.", sourceObjective = "Reist auf der Suche nach den Überresten zum Kun-Lai-Gipfel.", completion = "Ihr habt uns diesen Geist zurückgegeben. Er kann nun hier im Konservatorium frei umherstreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62630] = { id = 62630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle Geister, groß und klein", description = "Es ist Zeit für uns, einen weiteren Tiergeist wiederzubeleben.\n\nAuch wenn dieses Geschöpf Euch und der großen, geflügelten Kreatur, die es gefressen hat, normal erscheint, so war es doch für die anderen seiner Art etwas Besonderes.\n\nIhr solltet zu seinem grausigen Ruheplatz reisen und mit seinem Geist Zwiesprache halten, damit es sich uns im Konservatorium anschließt.", sourceObjective = "Reist auf der Suche nach den Überresten zum Tiragardesund.", completion = "Ihr habt uns diesen Geist zurückgegeben. Er kann nun hier im Konservatorium frei umherstreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62631] = { id = 62631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Welt wartet", description = "Wenn das Zeichen des Abgesandten am Nachthimmel leuchtet, festigen die Sterne ihre bestehenden Bande und knüpfen neue. Freundschaft wird nicht leichtfertig vergeben und nur durch Taten wird Treue bewiesen, aber Vertrauen stellt sich in diesen Tagen schneller ein. Bereist diese Region und helft, wo Ihr könnt, um Euch als würdig zu erweisen.", sourceObjective = "Schließt 20 Weltquests in den Schattenlanden ab.", completion = "Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[62632] = { id = 62632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein brennender Pfad durch die Zeit", description = "Der gleißende Stern wirft sein Licht auf das Land und lässt die Erde verdorren und ganze Landschaften versengen. Es ist ein gnadenloser, fast schon bösartiger Stern. Unter seinem Einfluss eröffnen sich neue Wege... zu weit entfernten Orten und sogar zu weit entfernten Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Zeichens vollständig zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Besiegt 5 Zeitwanderungsschlachtzugsbosse oder Zeitwanderungsdungeons.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[62633] = { id = 62633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gefrorener Weg durch die Zeit", description = "Der kalte Stern wirft sein frostiges Licht auf das Land und selbst die Schatten ziehen sich zurück. Es ist ein Stern wie kein zweiter, der alle Wärme und Leben entzieht. Unter seinem Einfluss eröffnen sich neue Wege... zu weit entfernten Orten und sogar zu weit entfernten Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Zeichens vollständig zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Besiegt 5 Zeitwanderungsschlachtzugsbosse oder Zeitwanderungsdungeons.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[62634] = { id = 62634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verwüsteter Pfad durch die Zeit", description = "Der Stern des Zerstörers bedeckt das Land mit seinem durchdringenden Licht, sodass sich selbst die Geister in die Schatten zurückziehen. Dieser Stern ist wie kein anderer am Himmel. Er offenbart selbst die Schwächen der furchtlosesten Helden. Unter seinem Einfluss eröffnen sich neue Wege... zu weit entfernten Orten und sogar zu weit entfernten Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Zeichens vollständig zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Besiegt 5 Zeitwanderungsschlachtzugsbosse oder Zeitwanderungsdungeons.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[62635] = { id = 62635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verschleierter Pfad durch die Zeit", description = "Der verschleierte Stern lässt sein Flackern durch die flüsternden Wogen der gespenstischen Nebel gleiten. Wie ein düsterer Schleier legt sich das Schauspiel über die Geheimnisse und Gefahren des Landes. Unter seinem Einfluss eröffnen sich neue Wege - zu weit entfernten Orten und sogar zu weit entfernten Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Zeichens vollständig zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[62636] = { id = 62636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wilder Weg durch die Zeit", description = "Der brutale Stern wirft sein Licht auf das Land und droht, alle zu zerschmettern, die ihm im Weg stehen. Dieser Stern hat viele Seiten: Er ist urgewaltig, wild und erhaben. Unter seinem Einfluss eröffnen sich neue Wege... zu weit entfernten Orten und sogar zu weit entfernten Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Zeichens vollständig zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[62637] = { id = 62637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Aufruf zur Schlacht", description = "Der Lieblingsstern der Kriegsherren und Generäle beherrscht den Himmel und bringt allen Strategen Glück. Einige sagen, der Kampfstern schärft die Instinkte von Kommandanten so weit, dass es Wahrsagerei gleicht. Wenn Ihr je daran gedacht habt, Euch auf dem Schlachtfeld zu beweisen, ist jetzt der richtige Zeitpunkt dafür.", sourceObjective = "Gewinnt 4 Schlachtfeldpartien.", completion = "Ich vermute, dass Eure Schlachten gut verlaufen sind. Eigentlich ist das keine Vermutung. Ich weiß es. Ich wusste es schon immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[62638] = { id = 62638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgesandter des Krieges", description = "Wenn das Zeichen des Kriegers am Nachthimmel leuchtet, ist das Schicksal den Wagemutigen hold. Mächtige Feinde können noch größere Belohnungen erbringen. Begebt Euch tief in die Höhlen und Festungen, um Euch als würdig zu erweisen.", sourceObjective = "Schließt 4 Dungeons auf dem Schwierigkeitsgrad 'Mythisch' ab.", completion = "Gut gemacht, {name}. Ich wusste, dass Ihr es schaffen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[62639] = { id = 62639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierchampion", description = "Dies ist eine wahrhaft ungewöhnliche Sternenkonstellation. Sie ist dafür verantwortlich, dass die kleinsten Kreaturen ungewöhnliche Fähigkeiten entwickeln. Keiner unserer Weisen kann dieses Phänomen erklären, aber für geschickte Zähmer ist dies eine perfekte Gelegenheit, ihre Fähigkeiten gegen andere auf die Probe zu stellen.", sourceObjective = "Besiegt 5 Spieler über 'Kampf finden' mit einer Gruppe aus Haustieren auf Stufe 25.", completion = "Gut gemacht, {name}. Ihr habt Mut bewiesen, alle Herausforderungen auf dem Wege bestanden und Euch über Tage hinweg den Platz erkämpft, der Euch zusteht.", sourceObjectiveStatus = "unverified-source-field" }
quests[62640] = { id = 62640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arena ruft", description = "Diese Sternenkonstellation ist ein düsteres Omen. Sie ruft Blutlust hervor und zwingt Krieger zur Teilnahme an tödlichen Nahkämpfen. Die Arenameister verdienen gut dieser Tage. Vermutlich wissen sie nicht einmal, warum so viele Krieger in ihren Arenen antreten wollen. Neben der fiebrigen Spannung erwarten alle, die mutig oder töricht genug sind, sich diesen Arenakämpfen zu stellen, große Belohnungen...", sourceObjective = "Gewinnt 10 Arenageplänkel.", completion = "Gut gemacht, {name}. Ich wusste, Ihr würdet es schaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62642] = { id = 62642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - SL - Heroic Random - 1st" }
