quests[62647] = { id = 62647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - SL - Raid Finder - Nth" }
quests[62653] = { id = 62653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der Inquisition", sourceObjective = "Besiegt einen beliebigen Inquisitor in den Hallen der Sühne.\n\nArchivar Fane kann Euch Inquisitorsündensteine geben, die Euch bei Eurer Jagd helfen.", completion = "<Archivarin Janeera blickt nicht von ihrer Schriftrolle auf, während sie antwortet.>\n\nZur Kenntnis genommen und vermerkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[62654] = { id = 62654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlundgänger", description = "Ich glaube, jetzt ist die Zeit gekommen, dass Ihr gehen solltet.\n\nIhr seid <ein Schlundgänger/eine Schlundgängerin> und könnt den Portalstein zwischen dem Schlund und den Ländern jenseits davon aktivieren. Eure Freunde tragen vielleicht nicht den gleichen Titel, aber es gibt einen Weg, auch sie durch das Tor gehen zu lassen.\n\nSeelen können verbunden werden. Wenn jemand seine Seele mit der Euren verbindet, während Ihr den Portalstein aktiviert, könntet Ihr beide theoretisch von hier fortgehen. Selbst flüchtige Verbindungen könnten brauchbare Ergebnisse liefern.\n\nGeht mit Euren beiden anderen Gästen und prüft, ob meine Hypothese korrekt ist.", sourceObjective = "Verbindet Euch mit Darion und Alexandros und helft ihnen, den Schlund zu verlassen.", completion = "Ihr kehrt unversehrt zurück. Und nicht nur mit Darion, sondern auch mit seinem Vater. Ihr seid weiterhin erfolgreich, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[62658] = { id = 62658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belohnungsquest für Shadowlandsdungeon" }
quests[62691] = { id = 62691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf aus Revendreth", description = "Da draußen gibt es viele Probleme, Boss. Große, kleine, schlimm müffelnde, das sind viele.\n\nWenn wir uns Denathrius vorknöpfen wollen, müssen wir als Erstes hier in Revendreth aufräumen.\n\nDas kriegen wir hin, oder? Dann suchen wir uns neue Verbündete, auf diese Weise gelangen wir wohl auch an neue Anima.\n\nDas ist ein echter Weckruf. Wir sollten unbedingt sofort loslegen.\n\nSchwingt Euch da raus und macht Euch die Stiefel matschig!", sourceObjective = "Schließt 3 Weltquests in Revendreth ab.", completion = "Ihr habt heute was Gutes getan, und deshalb sind wir jetzt sicherer. Ich werfe ja sonst nich' mit Komplimenten um mich, aber Ihr habt Euch echt gut geschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62692] = { id = 62692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf aus der Bastion", description = "Der Zweifel nagt an unseren Truppen und unsere Tempel werden angegriffen. Wenn wir den restlichen Schattenlanden helfen wollen, sollten wir hier in der Bastion damit beginnen.\n\nReist über die goldenen Felder und vernichtet das Böse, wo immer Ihr es findet. Wir werden unterdessen unsere Truppen wiederaufbauen und unsere Animavorräte auffüllen, um wieder kampfbereit zu sein.\n\nHeute beschreitet Ihr den Weg des Mutes, das ist Eure Berufung. Zeigt unserem Volk, dass Zweifel hier keinen Platz haben.", sourceObjective = "Schließt 3 Weltquests in der Bastion ab.", completion = "Die Hügel singen von Eurer Ehre und Eurem unerschütterlichen Glauben. Jeder Sieg gibt unseren Truppen neuen Mut!\n\nEhre sei der Bastion, Ehre sei der Archon und Ehre sei dem Schlundgänger!", sourceObjectiveStatus = "unverified-source-field" }
quests[62693] = { id = 62693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf aus dem Ardenwald", description = "Der Ardenwald ist gespalten, seine Wurzeln leiden. Doch bevor unsere Lichtungen nachwachsen können, müssen wir das Böse aufdecken, das hier schwärt.\n\nWir rufen heute nach Euch, um unsere Wälder zu verteidigen. Schreitet auf den offenen Pfaden durch unser Land, um unseren Verbündeten zu helfen und unsere Gegner zu besiegen. Auf diese Weise erneuern wir unsere Streitkräfte und unsere Anima. Mit der Zeit wird unsere Hoffnung wieder erblühen.\n\nWir setzen unser Vertrauen in Euch, unseren neuesten Setzling.", sourceObjective = "Schließt 3 Weltquests im Ardenwald ab.", completion = "Eure Taten heute haben unsere Bande gestärkt und unsere Wurzeln graben sich tiefer in den Boden als je zuvor. Wir werden uns des Ansturms der Feinde, die uns plagen, erwehren, da die Haine sich dank Euch zur Verteidigung miteinander verflechten.", sourceObjectiveStatus = "unverified-source-field" }
quests[62694] = { id = 62694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf aus Maldraxxus", description = "Ab heute beschreiten wir den Weg zum Sieg.\n\nDer Gegner umzingelt uns von allen Seiten. Helft unseren Truppen in der Schlacht und kehrt mit den Ressourcen zurück, die wir für den Krieg benötigen.\n\nSobald unsere Heimatfront gesichert ist, können wir über ihre Grenzen hinaus aktiv werden.\n\nSo lautet Euer Ruf. Niederlagen sind inakzeptabel.", sourceObjective = "Schließt 3 Weltquests in Maldraxxus ab.", completion = "Unsere konkurrierenden Häuser werden zweimal darüber nachdenken, bevor sie einen Fuß aus ihren Hochburgen setzen. Blut und Ruhm für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[62695] = { id = 62695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf zur Hilfe", description = "Es hat sich eine Möglichkeit ergeben, mit deren Hilfe Ihr den Einwohnern von Revendreth perfekt Euer... Können beweisen könnt.\n\nSprecht mit Rendel. Dieser Gräber ist verstörend zielführend bei der Ausarbeitung von Plänen. Und er sagt, dass er schon einen Plan für Euch habe.", sourceObjective = "Sprecht mit Rendel.", completion = "Gut, dass Ihr Euch dieser Herausforderung stellt. Es gibt viel zu tun hier in Revendreth. Hoffentlich seid Ihr bereit, Euch die Hände schmutzig zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62697] = { id = 62697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf zur Hilfe", description = "<Laurel spielt eine traurige Melodie auf ihrer Harfe.>\n\nUnsere Haine welken und verdorren,\nund Gegner warten vor unseren Toren!\nDer Wald ruft in Trauer: \n\"Bitte helft uns, sonst sind wir verloren!\"\n\n<Die Melodie wird zu einem Ruf zu den Waffen.>\n\nOh <Jäger/Jägerin>, antwortet jetzt auf unseren Ruf!\nDer Ardenwald braucht Eure Macht!\nDie Abgesandte Blodwyn wird Euch einen Auftrag erteilen,\n zu reiten mit der Wilden Jagd heute Nacht!", sourceObjective = "Sprecht mit Blodwyn.", completion = "Danke für Euren Besuch, ich vertraue Euch eine wichtige Aufgabe an. Damit der Ardenwald neu wachsen kann, müssen wir seinen Bewohnern helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62698] = { id = 62698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf zur Hilfe", description = "Die Elysische Feste braucht so viel Anima wie möglich, damit wir von ihr vollen Gebrauch machen können.\n\nUnsere Tempel wimmeln nur so vor Herausforderungen. Erfüllt sie, um Anima zu beschaffen, das uns hier im Sanktum von Nutzen sein wird.\n\nSprecht zuerst mit Hermestes, er wird Euch auf den Weg des Mutes führen.", sourceObjective = "Sprecht mit Hermestes.", completion = "Ich wusste, Ihr würdet dem Ruf folgen, Schlundgänger. Es gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[62700] = { id = 62700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche des Turms", description = "Als ersten Schritt zum Erhalt der Macht müsst Ihr etwas beschaffen... Ja, ich glaube, ich erinnere mich wieder.", sourceObjective = "Sammelt 1250-mal Seelenasche in Torghast.", completion = "Ja, das sollte genügen, um die Runen zu gravieren, jedenfalls bei geringerer Ausrüstung. \n\nMächtige Gegenstände erfordern mehr... mehr... Seelenasche. Ja, Seelenasche.\n\nIhr solltet sie gut verwahren. Ich werde Euch zu gegebener Zeit danach fragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62704] = { id = 62704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fäden des Schicksals", description = "Es ist meine Pflicht, die Stränge des Schicksals zu erkennen, die wundersamen Möglichkeiten der Vorsehung.\n\nDas Schicksal umfließt Euch, <Sterblicher/Sterbliche>. Es wandelt sich stetig. Doch ich habe seine Bewegungen beruhigt, um Euch eine... Wahl zu bieten.\n\nIhr könnt auf die gleiche Weise durch die Schattenlande reisen wie die vor Euch.\n\nOder Ihr könnt einen anderen Weg wählen. Schließt jetzt einen Pakt, dann könnt Ihr frei durch die Reiche des Todes wandeln, um Euer eigenes Schicksal zu schmieden.\n\nWas sagt Ihr, <Sterblicher/Sterbliche>?", sourceObjective = "Sprecht mit Schicksalsschreiber Roh-Tahl und entscheidet Euch, wie Ihr die Schattenlande erleben möchtet.", progress = "Am Schicksal lässt sich nicht rütteln. Nehmt Ihr es an, gibt es kein Zurück.", completion = "Eure Wahl ist getroffen. Die Vorsehung wird Euch leiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[62705] = { id = 62705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Tempel durchsuchen" }
quests[62707] = { id = 62707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Elysischen Felder", description = "Reist zur Bastion, dem ewigen Zuhause der geflügelten Kyrianer.\n\nLasst Euch nicht von Ihren goldenen Feldern und glänzenden Türmen täuschen... die große Animadürre hat die Kyrianer geschwächt und an den Rand eines Bürgerkriegs mit ihren eigenen gefallenen Brüdern gedrängt.\n\nEure Unterstützung wird von großem Nutzen für sie sein. Sucht am Wegekreuz namens Heldenrast nach der, die Kalisthene genannt wird. Sie kann Euch weiterhelfen.\n\nPfadschreiber Roh-Avonavi im Ring der Übertragung wird für Euren Transport sorgen.", sourceObjective = "Sprecht mit Kalisthene bei der Heldenrast in der Bastion.", completion = "Warum seid Ihr in unser Reich gekommen, Sterblicher?", sourceObjectiveStatus = "unverified-source-field" }
quests[62712] = { id = 62712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zermürbungskrieg" }
quests[62714] = { id = 62714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für eine Akolythin", description = "Die von Euch überbrachten Materialien waren für meine Zwecke mehr als ausreichend. Dafür schulde ich Euch Dank.\n\nIch habe eine Idee, wozu der Rest dienen könnte.\n\nEine gute Freundin von mir wurde jüngst zur Akolythin im Tempel der Reinheit ernannt. Da Ihr neu hier seid, erspare ich Euch die Einzelheiten, doch es handelt sich um eine große Ehre, in einem Tempel zu dienen, bevor der Aufstieg erreicht wird.\n\nZu diesem Erfolg möchte ich Ihr mit einem Geschenk gratulieren. Bringt Ihr dieses Paket zu Akolythin Amalthina?", sourceObjective = "Bringt Klysteres Geschenk zu Akolythin Amalthina im Tempel der Reinheit.", progress = "Willkommen im Tempel der Reinheit. Wie kann ich zu Diensten sein?", completion = "Was ist das?\n\n<Sie öffnet das Paket. Ein sanftes Lächeln erscheint auf ihrem Gesicht.>\n\nWie wundervoll. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[62715] = { id = 62715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als ein Geschenk", description = "Ihr habt keine Ahnung, was Ihr gerade überbracht habt, oder?\n\n<Sie öffnet das Paket, ein Kranz aus Lariongefieder kommt zum Vorschein.>\n\nIch erkläre es Euch, doch zuerst... möchte ich den Gefallen erwidern.\n\nKlystere und ich suchen häufig einen Ort der Ruhe nördlich von hier auf dem Weg des Mutes auf. Zu unserer Muße pflanzten wir dort eine Blume.\n\nBringt mir ihre Blüte, wenn Ihr so gütig seid. Dann erkläre ich Euch, was es mit diesem Geschenk auf sich hat.", sourceObjective = "Beschafft 1 kultivierte Windblüte", progress = "Habt Ihr den besagten Ort gefunden? Und die Blume?", completion = "Perfekt. Ich danke Euch für Eure Mühe.", sourceObjectiveStatus = "unverified-source-field" }
quests[62716] = { id = 62716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedervorstellungen", description = "Ihr habt Euren Weg gewählt, doch das Schicksal der Schattenlande ist noch unbestimmt.\n\nDie Macht des Verbannten wächst. Euch und anderen Eurer Art fällt es zu, ihn aufzuhalten.\n\nSprecht mit Tal-Inara, der geehrten Stimme der Richterin, um einen Pakt zu wählen. Ihn zu stärken, ist unsere beste Chance auf den Sieg.\n\nLasst Euch stets von der Vorsehung leiten, {name}.", sourceObjective = "Sprecht mit Tal-Inara in der Enklave in Oribos.", completion = "Ah, {name}. Ich habe mich schon gefragt, wann Ihr kommt. Wir benötigen Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[62717] = { id = 62717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venari Rep Token Tracking" }
quests[62718] = { id = 62718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenrast", description = "Angesichts der Neuzugänge in der Bastion hat Kalisthene die Animaportale in der Heldenrast erneut aktiviert!\n\nWer atemberaubende Ausblicke wünscht, exzellente Provostleistungen sowie alle möglichen Übungs- und Reparatureinrichtungen, der sollte diese bemerkenswerten Orte baldmöglichst besuchen.\n\nFolgt einfach dem Pfad nach Norden und haltet Euch beim Wegekreuz rechts.\n\nKalisthene begrüßt anlässlich dieses höchst freudigen Anlasses alle Neuzugänge persönlich!", sourceObjective = "Sprecht mit Kalisthene in der Heldenrast.", completion = "Willkommen in der Heldenrast, dem Wegekreuz der Bastion. Hier werdet Ihr viel Hilfe für Eure Reise finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[62719] = { id = 62719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzten Teile", description = "Die letzten Komponenten, die Ihr beschaffen müsst, sind... Gefäße... Runengefäße! Rüstung, welche die Macht für die Ermächtigung enthält.\n\nUnd... Mächte? Nein... Schreiben? Ja! Schreiben verleihen Eurem Gegenstand die Macht, Eure persönlichen Stärken zu steigern. Aber sie können nicht gleich sein. Nein, die beiden müssen verschiedene Vorteile bieten.\n\nAll diese erhaltet Ihr von Seelen, die über das richtige Handwerkswissen verfügen.\n\nUnd zuletzt, mehr von meinen Erinnerungen. Erinnerungen der Runen, der Mächte... von mir selbst.", sourceObjective = "Beschafft eine Erinnerung des Runenmetzes, ein für Eure Klasse angemessenes Rüstungsrunengefäß und zwei verschiedene Schreiben. Diese Gegenstände könnt Ihr durch Herstellung erhalten oder im Auktionshaus finden.", progress = "Habt Ihr die restlichen Gegenstände beschaffen können?", completion = "Ihr habt alle notwendigen Teile gesammelt. Nun müssen sie nur noch zusammengesetzt werden.\n\nSprecht wieder mit mir, wenn Ihr bereit seid, dann erschaffe ich den Preis, nach dem Ihr strebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[62720] = { id = 62720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gefallene Baum" }
quests[62721] = { id = 62721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dekonstruktion des Problems" }
quests[62723] = { id = 62723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Schutz der Bastion", description = "Ihr seid zwar <kein Aspirant/keine Aspirantin>, doch ich begrüße jede Hilfe, die Oribos uns in diesen düsteren Zeiten sendet.\n\nBitte helft unserem Volk so gut Ihr könnt. Probleme gibt es genug, ob Animadürre oder die heimtückischen Verschmähten, die von allen Seiten herankriechen.\n\nGewährt uns dies, dann sorge ich persönlich dafür, dass unsere allmächtige Archon Eure Dienste an den Kyrianern erhört. Merkt Euch meine Worte und folgt dem Pfad.", sourceObjective = "Helft der Bastion, indem Ihr Nebenquests, Weltquests und Bonusziele abschließt sowie seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons der Bastion besiegen.", completion = "Seit Eurer Ankunft hat sich die Kunde von Euren Taten in der Bastion verbreitet.\n\nIhr habt Euch als würdiger Verbündeter der Kyrianer erwiesen. Nehmt zum Dank dieses Geschenk und geht und dient.\n\nMögen sich unsere Pfade bald erneut kreuzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62724] = { id = 62724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ye Olde Test of Strength" }
quests[62725] = { id = 62725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of Guile" }
quests[62726] = { id = 62726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ye Olde Test of Fortitude" }
quests[62727] = { id = 62727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "9.0 Rated PvP Incentive - Shadowlands Season 1 Exclusive Mount" }
quests[62728] = { id = 62728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "9.0 Rated PvP Incentive - Shadowlands Season 1 Saddle" }
quests[62729] = { id = 62729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Oribos", description = "Seit Eurer Ankunft habt Ihr Euch als <würdiger Verbündeter/würdige Verbündete> der Bastion erwiesen, {name}. Ich wünschte, Ihr könntet hierbleiben, doch andere Reiche in den Schattenlanden benötigen Eure Unterstützung dringender.\n\nKehrt nach Oribos zurück und geht zu Tal-Inara. Sie wird Euch bei Eurem nächsten Schritt hilfreich sein.\n\nMöge die Archon über Euch wachen.", sourceObjective = "Sprecht mit Tal-Inara in Oribos.", completion = "Ihr habt Eure Vorsehung erfüllt. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[62730] = { id = 62730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frucht der Götter", description = "Ihr mögt süße Früchte? \n\nDie Provosten züchten die süßesten Purianfrüchte. Die sind etwas ganz Besonderes! Ihr findet sie an vielen Orten in der Bastion. Kann von vielerlei Nutzen sein. \n\nIhr könnt sie essen.\n\nSie können Euch Segen bringen.\n\nDie Provosten geben Euch Schätze dafür.\n\nFindet sie, dann zeige ich es Euch!", sourceObjective = "Bringt Elios 1 reife Purianfrüchte.", progress = "Habt Ihr süße Purianfrüchte gefunden?", completion = "Ja, sehr reif und süß. Muss rasch nutzen, bevor sie verderben!", sourceObjectiveStatus = "unverified-source-field" }
quests[62732] = { id = 62732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Locus-Fokus" }
quests[62733] = { id = 62733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süßer Tribut", description = "Purianfrucht ist lecker, aber Geben noch besser.\n\nBei der Provostenstatue ist verschlossene silberne Schließkassette. Gebt reife Purianfrucht als Tribut.\n\nEs gibt schöne Überraschung!\n\nVersucht Ihr?", sourceObjective = "Platziert eine reife Purianfrucht auf dem Tributtablett der Provostenstatue.", completion = "Hoffentlich gefiel Euch Überraschung! \n\nBei mehr silbernen Schließkassetten gebt auch reife Purianfrüchte!\n\nUh-hu! Ihr wollt Schlüssel zu meiner Goldenen Truhe? Fragt mich nach Provost des Tages!", sourceObjectiveStatus = "unverified-source-field" }
quests[62735] = { id = 62735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindselige Erinnerungen" }
quests[62736] = { id = 62736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maldraxxische Räumungsklage" }
quests[62737] = { id = 62737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aspirant für einen Tag" }
quests[62738] = { id = 62738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine frische Klinge", description = "Obwohl sie einst vereint die Schattenlande verteidigt haben, liegen die Häuser von Maldraxxus jetzt im Zwist miteinander.\n\nIn ihrem Reich prallen die Armeen aufeinander, selbst die Bastion bleibt nicht verschont. Nur noch die Nekrolords halten dem Primus die Treue.\n\nSprecht mit Secutor Mevix an der Düsteren Wehr in Maldraxxus. Mit seinem strategischen Gespür wird er Euch dorthin senden, wo Ihr am meisten gebraucht werdet.\n\nPfadschreiber Roh-Avonavi im Ring der Übertragung kann für Euren Transport sorgen.", sourceObjective = "Sprecht mit Secutor Mevix an der Düsteren Wehr in Maldraxxus.", completion = "Ah, eine weitere Klinge an unserer Seite! Und Ihr seid noch nicht einmal tot!", sourceObjectiveStatus = "unverified-source-field" }
quests[62739] = { id = 62739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederherstellung des Gleichgewichts", description = "Der Ardenwald ist für den Wiedergeburtszyklus der Nachtgeister, die sein Reich betreten, von großer Wichtigkeit.\n\nLeider führte die Animadürre zum Verlust ganzer Haine, und diese Seelen werden ihren Zyklus nie vollenden.\n\nJetzt wollen die Feinde auch noch den Rest des einst ruhigen Walds zerstören, sie bedrohen den bereits in Mitleidenschaft gezogenen Hof der Nacht. \n\nLady Mondbeere vom Hof bittet um Hilfe. Pfadschreiber Roh-Avonavi im Ring der Übertragung wird für Euren Transport sorgen.", sourceObjective = "Sprecht mit Lady Mondbeere beim Herz des Waldes im Ardenwald.", completion = "Willkommen! Was führt Euch ins Herz des Waldes?", sourceObjectiveStatus = "unverified-source-field" }
quests[62740] = { id = 62740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düstere Ambitionen", description = "Prinz Renathal wagt eine kühne Rebellion gegen seinen Vater, den ruchlosen Grafen Denathrius, der uns alle betrog, indem er Revendreths reiche Animavorräte in den Schlund schüttete.\n\nIhr müsst nach Revendreth reisen, um Renathal bei seinen Bemühungen zu unterstützen. Er ist unsere größte Hoffnung, um die Ordnung in Revendreth wiederherzustellen.\n\nPfadschreiber Roh-Avonavi im Ring der Übertragung wird für Euren Transport sorgen.", sourceObjective = "Sprecht mit Prinz Renathal in der Krypta unter Dunkelhafen in Revendreth.", completion = "Was verschafft mir das Vergnügen eines Sterblichen, der Revendreth zu solch... ungelegener Zeit besucht?", sourceObjectiveStatus = "unverified-source-field" }
quests[62741] = { id = 62741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Qual der Wahl" }
quests[62742] = { id = 62742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meidet sie wie die Pest" }
quests[62743] = { id = 62743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleichender Verfall" }
quests[62748] = { id = 62748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste Maldraxxus", description = "Wir brauchen jede Hilfe, die wir kriegen können! Mit aller Kraft gelingt es noch, unsere Stellung gegen die anderen Häuser zu halten, an ein Vorrücken ist kaum zu denken.\n\nUm ehrlich zu sein, haben wir Eure Klinge bitter nötig. Kämpfe und Gegner gibt es genug, oder müde Soldaten, die eine Pause benötigen.\n\nHelft uns, die Kontrolle über Maldraxxus zurückzuerlangen, dann sollt Ihr im Namen des Primus reich belohnt werden.", sourceObjective = "Helft Maldraxxus, indem Ihr Nebenquests, Weltquests und Bonusziele abschließt sowie seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons von Maldraxxus besiegen.", completion = "Alle Meldungen berichten nur eines: Ihr habt dem Haus der Auserwählten Sieg auf Sieg gebracht!\n\nIm Namen aller, die dem Primus dienen, spreche ich Euch meinen ewigen Dank aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[62761] = { id = 62761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Oribos", description = "Ich wäre ein schlechter Stratege, wenn ich nicht wüsste, wann eine Mission erfüllt ist.\n\nBevor Maldraxxus wieder in altem Glanz erstrahlt, ist noch viel zu tun, doch dank Eurer Mühen ist dieser Tag nun nicht mehr fern. \n\nAndere Reiche sind dringender auf Euer Geschick angewiesen. Ihr solltet nach Oribos zurückkehren und Euch darum kümmern.", sourceObjective = "Sprecht mit Tal-Inara in Oribos.", completion = "Ihr habt Euch in Maldraxxus gut geschlagen. Der Pfad voraus ist frei.", sourceObjectiveStatus = "unverified-source-field" }
quests[62763] = { id = 62763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung des Hofes", description = "Überall werden die Haine angegriffen! Wir sind einfach zu wenige, um sie alle zu beschützen!\n\nIhr könntet unsere einzige Hoffnung sein.\n\nWenn wir die Ordnung nicht wiederherstellen, werden noch mehr kostbare Seelen verloren gehen. Bitte, helft so gut Ihr könnt, egal wem. Mein Herz kann noch mehr Schmerz nicht ertragen!\n\nKeine Sorge, ich werde der Winterkönigin von Euren Taten berichten!", sourceObjective = "Helft dem Ardenwald, indem Ihr Nebenquests, Weltquests und Bonusziele abschließt sowie seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons im Ardenwald besiegen.", completion = "Ihr habt nicht nur dem Ardenwald einen großen Dienst erwiesen, sondern ebenfalls den unzähligen Naturgeistern, die wir schützen.\n\nDanke. Heute seid Ihr ein Held des Ardenwaldes!", sourceObjectiveStatus = "unverified-source-field" }
quests[62773] = { id = 62773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traumschreinbecken" }
quests[62774] = { id = 62774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhige Teiche" }
quests[62775] = { id = 62775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwindende Hain" }
quests[62776] = { id = 62776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Oribos", description = "Ich wünschte, Ihr könntet euch hier noch ein wenig entspannen, vielleicht eine Aufführung im Sternseeamphitheater genießen, aber es bleibt keine Zeit!\n\nDie anderen Reiche benötigen ebenfalls Eure Hilfe.\n\nIhr werdet stets ein Freund des Hofes bleiben, doch Ihr müsst nach Oribos zurückkehren. Die Schattenlande brauchen Euch!", sourceObjective = "Sprecht mit Tal-Inara in Oribos.", completion = "Eure Leistungen im Ardenwald sind nicht unbemerkt geblieben, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[62778] = { id = 62778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung von Revendreth", description = "Denathrius muss um jeden Preis aufgehalten werden. Solange seine Truppen noch einen Großteil von Revendreth kontrollieren, können wir ihn jedoch nicht ausschalten.\n\nEs gibt viel zu tun, wenn Ihr uns helfen wollt. Ihr könnt Euch die Verbündeten meines Vaters vorknöpfen. Jede Hilfe wird von Nutzen sein.\n\nFür die Schattenlande steht zu viel auf dem Spiel, wir dürfen nicht scheitern. Ich werde dafür sorgen, dass Ihr für Eure Mühen fürstlich belohnt werdet.", sourceObjective = "Helft Revendreth, indem Ihr Nebenquests, Weltquests und Bonusziele abschließt sowie seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons von Revendreth besiegen.", completion = "Für Eure Unterstützung unserer Sache gilt Euch mein aufrichtiger Dank. Gemeinsam werden wir Denathrius' Griff um unser Reich sprengen und so mein Volk befreien.\n\nIch kann Euch nicht so viel anbieten, wie ich möchte, doch ich hoffe, es genügt, bis der Sieg errungen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[62779] = { id = 62779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Oribos", sourceObjective = "Sprecht mit Tal-Inara in Oribos.", completion = "Dank Eurer Mühen ist Revendreth nun gestärkt. Die Vorsehung ist klar.", sourceObjectiveStatus = "unverified-source-field" }
quests[62780] = { id = 62780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parasiten der Realität" }
