quests[62784] = { id = 62784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeremonienbetrüger" }
quests[62785] = { id = 62785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich könnte ein Streiter sein", description = "Haltet ein, <Bruder/Schwester>. \n\nWenn Ihr wirklich im Ring kämpfen wollt, braucht Ihr einen Manager. \nIhr könnt Euch glücklich schätzen, dass ich da jemanden kenne. Gerade sind ein paar Plätze in seiner Kämpferriege frei geworden, und Ihr seid genau die Art {class}, die er braucht.\n\nEr heißt Louison, Ihr findet ihn beim Tor östlich von hier.\n\nSagt ihm, dass ich Euch schicke, <Bruder/Schwester>.", sourceObjective = "Sprecht mit Louison.", completion = "Oh, Anzio schickt Euch? Ha, und ich dachte, Ihr seid bloß ein neugieriger Fan.\n\nJa, Ihr seht genau wie die Art {class} aus, die ich brauche!", sourceObjectiveStatus = "unverified-source-field" }
quests[62789] = { id = 62789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von hohem Ruhm", description = "Je mehr Ihr unseren heiligen Pakt in den Schattenlanden fördert, umso stärker wird Eure Verbindung mit uns.\n\nEuer Ruhm wird Euch mit der Zeit viele Vorteile einbringen.\n\nBegebt Euch zu Iona Himmelsklinge, die sich vor der Festung nahe des Emblems des Aufstiegs befindet. Sie wird Euch verdeutlichen, wie ruhmvoll der Pfad ist.", sourceObjective = "Sprecht mit Iona Himmelsklinge.", completion = "Ich grüße Euch, Schlundgänger. Es ist mir eine Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[62790] = { id = 62790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad nährt", description = "Alle, die dem Pfad folgen, erhalten dank ihrer tugendhaften Verbindung mit unserem Pakt wertvolle Geschenke.\n\nDie Stärke dieser Bindung, auch als Ruhm bekannt, spiegelt sich in den glänzenden Türmen der Elysischen Feste selbst. Ihr besitzt zwar noch keinen Ruhm, werdet ihn jedoch erlangen, wenn Ihr uns in den Schattenlanden helft.\n\nSobald Ihr bereit seid, zeige ich Euch alles, wozu der Pfad imstande ist.", sourceObjective = "Untersucht Eure Ruhmstufe beim Pakt der Kyrianer.", completion = "Folgt stets dem Pfad, dann wird alles gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[62791] = { id = 62791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere kostbarste Ressource", description = "Ihr habt den Ruf gehört, <Schlundgänger/Schlundgängerin>, und unserem Reich wieder Frieden gebracht.\n\nBleibt wachsam, denn es werden noch mehr Hilferufe folgen.\n\nEure so pflichtbewusst gesammelte Anima wird der Feste gute Dienste leisten. Bringt sie gleich zu Haephus. Er wird sicherstellen, dass sie sicher ist, bis ihre Zeit kommt.\n\nGeht und dient.", sourceObjective = "Sprecht mit Haephus.", completion = "Der Schlundgänger kehrt triumphal zurück! Habt Ihr Anima dabei?", sourceObjectiveStatus = "unverified-source-field" }
quests[62792] = { id = 62792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Reservoir wartet", description = "Als der Animafluss in der Bastion versickerte, vertraute unsere mächtige Archon es mir an, über unsere Reserven zu wachen, bis sie gebraucht werden.\n\nIhr könnt alle Anima, die Ihr findet, in diesem Reservoir hier lagern. Ich werde mit meinem Leben und zum Ruhme der Archon darüber wachen.", sourceObjective = "Lagert Anima in das Reservoir Eures Sanktums ein.", progress = "Hier ist die Anima vor unseren Gegnern geschützt, die es auf sie abgesehen haben.", completion = "Jeder Tropfen ist kostbar. Ich werde sie hier sicher verwahren.", sourceObjectiveStatus = "unverified-source-field" }
